--
-- Name: a2(public.listings); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.a2(l public.listings) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select public.a2_fit(
    (select m.power_kw from public.motorcycles m where m.id = l.motorcycle_id),
    coalesce(l.text_signals, array[public.power_version(l.variant, l.description)]))
$$;

--
-- Name: a2_fit(numeric, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.a2_fit(p_power_kw numeric, p_text_signals text[]) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when 'a2_limited' = any (coalesce(p_text_signals, '{}')) then 'ready'
    when p_power_kw <= 35 then 'ready'
    when p_power_kw <= 70 then 'restrictable'
  end
$$;

--
-- Name: accept_favourite_share(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accept_favourite_share(p_code text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_owner uuid;
begin
  perform public.require_account();
  select owner_id into v_owner
  from public.favourite_shares
  where code = p_code and code_expires_at > now()
  for update;
  if v_owner is null then
    raise exception 'This link is not valid any more' using errcode = 'P0002';
  end if;
  if v_owner = auth.uid() then
    raise exception 'This is your own list' using errcode = '22023';
  end if;
  update public.favourite_shares
     set viewer_id = auth.uid(), code = null, code_expires_at = null
   where owner_id = v_owner;
  return v_owner;
end;
$$;

--
-- Name: account_quiet_at(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_quiet_at(p_user uuid, p_at timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(q.enabled, true)
     and public.in_quiet_hours(
           coalesce(q.start_hour, 23), coalesce(q.end_hour, 8),
           extract(hour from p_at at time zone 'Europe/Lisbon')::integer)
  from (select 1) one
  left join public.quiet_hours q on q.user_id = p_user
$$;

--
-- Name: ad_link_code(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ad_link_code(p_url text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case when public.ad_link_source(p_url) is not null
    then substring(p_url from '-(ID[0-9A-Za-z]+)\.html')
  end
$$;

--
-- Name: ad_link_source(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ad_link_source(p_url text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when p_url ~* '^https?://(www\.|m\.)?olx\.pt/d/(pt/)?anuncio/[^?#]*-ID[0-9A-Za-z]+\.html'
      then 'olx'
    when p_url ~* '^https?://(www\.|m\.)?standvirtual\.com/motos/anuncio/[^?#]*-ID[0-9A-Za-z]+\.html'
      then 'standvirtual'
  end
$$;

--
-- Name: bike_value_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bike_value_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid DEFAULT auth.uid() NOT NULL,
    motorcycle_id uuid NOT NULL,
    year integer NOT NULL,
    mileage integer,
    requested_at timestamp with time zone DEFAULT now() NOT NULL,
    waited boolean NOT NULL,
    answered_at timestamp with time zone,
    ad_url text,
    CONSTRAINT bike_value_requests_ad_url_check CHECK (((ad_url IS NULL) OR (public.ad_link_source(ad_url) IS NOT NULL))),
    CONSTRAINT bike_value_requests_mileage_check CHECK ((mileage >= 0)),
    CONSTRAINT bike_value_requests_year_check CHECK (((year >= 1990) AND (year <= 2100)))
);

--
-- Name: ad_listing(public.bike_value_requests); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ad_listing(r public.bike_value_requests) RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select case when r.ad_url is not null then public.listing_for_ad(r.ad_url) end
$$;

--
-- Name: add_catalog_model(text, text, integer, text, text, text[], integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_catalog_model(p_brand text, p_model text, p_min_year integer, p_olx_search text DEFAULT NULL::text, p_standvirtual_search text DEFAULT NULL::text, p_aliases text[] DEFAULT '{}'::text[], p_engine_cc_min integer DEFAULT NULL::integer, p_engine_cc_max integer DEFAULT NULL::integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_brand text := normalize(btrim(p_brand), NFC);
  v_model text := normalize(btrim(p_model), NFC);
  v_slug text;
  v_id uuid;
  v_range int4range := public.engine_range_from_name(v_model);
begin
  perform public.require_account();

  if nullif(v_brand, '') is null or nullif(v_model, '') is null then
    raise exception 'Brand and model are required' using errcode = '22023';
  end if;
  if p_min_year < 1990 or p_min_year > extract(year from now())::integer + 1 then
    raise exception 'Year % is out of range', p_min_year using errcode = '22023';
  end if;
  if p_engine_cc_min not between 1 and 3000
     or p_engine_cc_max not between 1 and 3000
     or p_engine_cc_min > p_engine_cc_max then
    raise exception 'Engine size range %-% is invalid',
      p_engine_cc_min, p_engine_cc_max using errcode = '22023';
  end if;

  if p_engine_cc_min is null and p_engine_cc_max is null then
    p_engine_cc_min := lower(v_range);
    p_engine_cc_max := upper(v_range) - 1;
  end if;

  v_slug := btrim(regexp_replace(lower(v_brand || '-' || v_model),
                                 '[^a-z0-9]+', '-', 'g'), '-');

  insert into public.motorcycles
    (brand, model, slug, min_year, is_active, aliases,
     olx_search, standvirtual_search, engine_cc_min, engine_cc_max)
  values
    (v_brand, v_model, v_slug, p_min_year, true,
     coalesce(p_aliases, '{}'),
     nullif(btrim(p_olx_search), ''),
     nullif(btrim(p_standvirtual_search), ''),
     p_engine_cc_min, p_engine_cc_max)
  returning id into v_id;

  insert into public.user_models (user_id, motorcycle_id, min_year)
  values (auth.uid(), v_id, p_min_year);

  return v_id;
exception
  when unique_violation then
    raise exception '% % is already in the list', v_brand, v_model
      using errcode = '23505';
end;
$$;

--
-- Name: admin_accounts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_accounts() RETURNS TABLE(user_id uuid, email text, created_at timestamp with time zone, last_sign_in_at timestamp with time zone, is_admin boolean, is_me boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform public.require_admin();
  return query
  select u.id, u.email::text, u.created_at, u.last_sign_in_at,
         exists (select 1 from public.app_admins a where a.user_id = u.id),
         u.id = auth.uid()
  from auth.users u
  where not coalesce(u.is_anonymous, false)
  order by u.created_at;
end;
$$;

--
-- Name: age_mileage_factor(integer, integer, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.age_mileage_factor(p_year_diff integer, p_km_diff integer, p_per_year numeric DEFAULT 0.04, p_per_1000km numeric DEFAULT 0.002) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select greatest(0.35, least(2.5, exp(
    p_per_year * coalesce(p_year_diff, 0)
    - p_per_1000km * coalesce(p_km_diff, 0) / 1000.0
  )))
$$;

--
-- Name: decimal_year(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decimal_year(p_day date DEFAULT CURRENT_DATE) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select extract(year from p_day)
         + (p_day - make_date(extract(year from p_day)::integer, 1, 1))
           / 365.25
$$;

--
-- Name: age_score(integer, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.age_score(p_year integer, p_points_per_year numeric DEFAULT 10, p_reference numeric DEFAULT public.decimal_year()) RETURNS smallint
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select case
    when p_year is null then null
    else greatest(0, least(100, round(
      100 - greatest(0, p_reference - (p_year + 0.5)) * p_points_per_year
    )))::smallint
  end
$$;

--
-- Name: answer_bike_value_requests(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.answer_bike_value_requests(p_started_at timestamp with time zone) RETURNS TABLE(id uuid, user_id uuid, brand text, model text, year integer, mileage integer, comparable_count integer, fair_price numeric, is_ad boolean, listing_id uuid, deal_score smallint, risk_score smallint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  return query
  with answered as (
    update public.bike_value_requests r
    set answered_at = now()
    from public.motorcycles m
    where r.answered_at is null
      and m.id = r.motorcycle_id
      and m.is_active
      and m.collected_since <= p_started_at
      and m.min_year <= greatest(r.year - 3, 1990)
      and (r.requested_at < now() - interval '1 day'
           or (r.ad_url is null
               and exists (select 1 from public.listings l
                           where l.motorcycle_id = m.id
                             and l.last_seen_at >= p_started_at))
           or (r.ad_url is not null
               and exists (select 1 from public.listings l
                           where l.id = public.listing_for_ad(r.ad_url)
                             and l.last_seen_at >= p_started_at)))
    returning r.id, r.user_id, r.motorcycle_id, r.year, r.mileage, r.ad_url
  )
  select a.id, a.user_id, m.brand, m.model, a.year, a.mileage,
         v.comparable_count, v.fair_price,
         a.ad_url is not null, l.id, l.deal_score, l.risk_score
  from answered a
  join public.motorcycles m on m.id = a.motorcycle_id
  cross join lateral public.bike_value(a.motorcycle_id, a.year, a.mileage) v
  left join public.listings l
    on a.ad_url is not null and l.id = public.listing_for_ad(a.ad_url)
  order by a.id;
end;
$$;

--
-- Name: api_usage(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_usage() RETURNS TABLE(service text, month_requests integer, last_month_requests integer, last_used_on date)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_month date := date_trunc('month', now() at time zone 'Europe/Lisbon')::date;
begin
  perform public.require_admin();
  return query
  select s.service,
         coalesce(sum(u.requests) filter (where u.day >= v_month), 0)::integer,
         coalesce(sum(u.requests) filter (
           where u.day >= v_month - interval '1 month' and u.day < v_month), 0)::integer,
         max(u.day)
  from unnest(array['api_ninjas', 'gemini']) s(service)
  left join public.api_usage u on u.service = s.service
  group by s.service
  order by s.service;
end;
$$;

--
-- Name: apply_listing_dates(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_listing_dates(p_source text, p_dates jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  n integer;
begin
  update public.listings l
  set published_at      = least(l.published_at,
                                (d.value ->> 'published_at')::timestamptz),
      site_refreshed_at = greatest(l.site_refreshed_at,
                                   (d.value ->> 'site_refreshed_at')::timestamptz)
  from jsonb_each(p_dates) d
  where l.source = p_source
    and l.source_listing_id = d.key
    and (l.published_at is distinct from
           least(l.published_at, (d.value ->> 'published_at')::timestamptz)
         or l.site_refreshed_at is distinct from
           greatest(l.site_refreshed_at,
                    (d.value ->> 'site_refreshed_at')::timestamptz));

  get diagnostics n = row_count;
  return n;
end;
$$;

--
-- Name: apply_listing_details(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_listing_details(p_source text, p_details jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  n integer;
begin
  update public.listings l
  set description            = coalesce(d.description, l.description),
      registrations          = coalesce(d.registrations, l.registrations),
      service_book           = coalesce(d.service_book, l.service_book),
      origin                 = coalesce(d.origin, l.origin),
      warranty_until         = coalesce(d.warranty_until, l.warranty_until),
      dealer_warranty_months = coalesce(d.dealer_warranty_months,
                                        l.dealer_warranty_months),
      published_at           = least(d.published_at, l.published_at),
      site_colour            = coalesce(d.site_colour, l.site_colour),
      -- A page without photos keeps the search's thumbnail.
      images                 = case when cardinality(d.images) > 0
                                    then d.images else l.images end,
      details_checked_at     = now(),
      photos_read_at         = now()
  from jsonb_to_recordset(p_details) as d(
    source_listing_id      text,
    description            text,
    registrations          smallint,
    service_book           boolean,
    origin                 text,
    warranty_until         date,
    dealer_warranty_months smallint,
    published_at           timestamptz,
    site_colour            text,
    images                 text[]
  )
  where l.source = p_source
    and l.source_listing_id = d.source_listing_id;

  get diagnostics n = row_count;
  return n;
end;
$$;

--
-- Name: apply_listing_facts(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_listing_facts(p_source text, p_facts jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  n integer;
begin
  -- Marks belong to the photos they were made on.
  delete from public.photo_marks k
  using public.listings l, jsonb_to_recordset(p_facts) as f(
    source_listing_id text,
    images            text[]
  )
  where k.listing_id = l.id
    and l.source = p_source
    and l.source_listing_id = f.source_listing_id
    and cardinality(f.images) > 0
    and f.images[1:3] is distinct from l.images[1:3];

  update public.listings l
  set year        = coalesce(f.year, l.year),
      mileage     = coalesce(f.mileage, l.mileage),
      mileage_from_text = l.mileage_from_text and f.mileage is null,
      variant     = coalesce(f.variant, l.variant),
      description = coalesce(f.description, l.description),
      location    = coalesce(f.location, l.location),
      images      = case when f.new_photos then f.images else l.images end,
      photos_hashed_at = case
        when f.new_photos and f.images[1:3] is distinct from l.images[1:3]
        then null else l.photos_hashed_at end,
      photos_examined_at = case
        when f.new_photos and f.images[1:3] is distinct from l.images[1:3]
        then null else l.photos_examined_at end,
      photos_examined_all_at = case
        when f.new_photos then null else l.photos_examined_all_at end
  from (
    -- As the phone-number trigger stores them, so an unchanged text
    -- compares equal.
    select r.source_listing_id, r.year, r.mileage,
           public.without_phone_numbers(r.variant) as variant,
           public.without_phone_numbers(r.description) as description,
           r.location, r.images,
           coalesce(cardinality(r.images) > 0
                    and r.images is distinct from s.images, false) as new_photos
    from jsonb_to_recordset(p_facts) as r(
      source_listing_id text,
      year              smallint,
      mileage           integer,
      variant           text,
      description       text,
      location          text,
      images            text[]
    )
    left join public.listings s
      on s.source = p_source and s.source_listing_id = r.source_listing_id
  ) f
  where l.source = p_source
    and l.source_listing_id = f.source_listing_id
    and (   (f.year is not null and f.year is distinct from l.year)
         or (f.mileage is not null
             and (f.mileage is distinct from l.mileage or l.mileage_from_text))
         or (f.variant is not null and f.variant is distinct from l.variant)
         or (f.description is not null
             and f.description is distinct from l.description)
         or (f.location is not null and f.location is distinct from l.location)
         or f.new_photos);

  get diagnostics n = row_count;
  return n;
end;
$$;

--
-- Name: apply_price_updates(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_price_updates(p_source text, p_prices jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  n integer;
begin
  update public.listings l
  set price = v.price
  from (
    select key as sid, value::numeric as price
    from jsonb_each_text(p_prices)
  ) v
  where l.source = p_source
    and l.source_listing_id = v.sid
    and l.price is distinct from v.price;

  get diagnostics n = row_count;
  return n;
end;
$$;

--
-- Name: apply_prices_before_drop(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_prices_before_drop(p_source text, p_prices jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  n integer;
begin
  update public.listings l
  set price_before_drop = v.price
  from (
    select key as sid, value::numeric as price
    from jsonb_each_text(p_prices)
    where value is not null
  ) v
  where l.source = p_source
    and l.source_listing_id = v.sid
    and (l.price_before_drop is null or v.price > l.price_before_drop);

  get diagnostics n = row_count;
  return n;
end;
$$;

--
-- Name: asking_price(public.listings); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.asking_price(l public.listings) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case when l.price >= 300 then l.price end
$$;

--
-- Name: auth_admin_request(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_admin_request(p_method text, p_path text, p_body jsonb DEFAULT NULL::jsonb) RETURNS TABLE(status integer, body jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_url      text;
  v_key      text;
  v_response extensions.http_response;
begin
  select s.decrypted_secret into v_url
  from vault.decrypted_secrets s where s.name = 'service_url';
  select s.decrypted_secret into v_key
  from vault.decrypted_secrets s where s.name = 'service_role_key';
  if v_url is null or v_key is null then
    raise exception 'Accounts are not available until the next collection'
      using errcode = '55000';
  end if;

  perform extensions.http_set_curlopt('CURLOPT_TIMEOUT_MS', '15000');
  v_response := extensions.http((
    p_method,
    v_url || '/auth/v1' || p_path,
    array[extensions.http_header('apikey', v_key),
          extensions.http_header('Authorization', 'Bearer ' || v_key)],
    'application/json',
    p_body::text
  )::extensions.http_request);

  status := v_response.status;
  body := case when v_response.content ~ '^\s*[\[{]'
               then v_response.content::jsonb end;
  return next;
end;
$$;

--
-- Name: bike_value(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bike_value(p_motorcycle_id uuid, p_year integer, p_mileage integer DEFAULT NULL::integer) RETURNS TABLE(comparable_count integer, fair_price numeric, low_price numeric, high_price numeric)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  with comparables as (
    select c.year, c.mileage, c.price,
           p_year is not null and abs(p_year - c.year) <= 3 as near
    from public.listings c
    where c.motorcycle_id = p_motorcycle_id
      and c.status in ('active', 'price_changed')
      and c.duplicate_of is null
      and c.price >= 300
      and (p_year is null or c.year is not null)
      and (p_mileage is null or c.mileage is not null)
  ),
  chosen as (
    select c.*
    from comparables c
    where c.near
       or (select count(*) from comparables n where n.near) < 5
  ),
  adjusted as (
    select ch.price * public.age_mileage_factor(
             p_year - ch.year,
             p_mileage - ch.mileage,
             coalesce(d.per_year, 0.04),
             coalesce(d.per_1000km, 0.002)
           ) as price
    from chosen ch
    left join public.model_depreciation d on d.motorcycle_id = p_motorcycle_id
  )
  select
    count(*)::integer,
    round((percentile_cont(0.5)  within group (order by price))::numeric, 2),
    round((percentile_cont(0.25) within group (order by price))::numeric, 2),
    round((percentile_cont(0.75) within group (order by price))::numeric, 2)
  from adjusted;
$$;

--
-- Name: bike_value_model(text, text, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bike_value_model(p_brand text, p_model text, p_olx_search text DEFAULT NULL::text, p_standvirtual_search text DEFAULT NULL::text, p_engine_cc_min integer DEFAULT NULL::integer, p_engine_cc_max integer DEFAULT NULL::integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_brand text := normalize(btrim(p_brand), NFC);
  v_model text := normalize(btrim(p_model), NFC);
  v_slug text;
  v_id uuid;
  v_range int4range := public.engine_range_from_name(v_model);
begin
  perform public.require_account();

  if nullif(v_brand, '') is null or nullif(v_model, '') is null then
    raise exception 'Brand and model are required' using errcode = '22023';
  end if;
  if p_engine_cc_min not between 1 and 3000
     or p_engine_cc_max not between 1 and 3000
     or p_engine_cc_min > p_engine_cc_max then
    raise exception 'Engine size range %-% is invalid',
      p_engine_cc_min, p_engine_cc_max using errcode = '22023';
  end if;

  v_slug := btrim(regexp_replace(lower(v_brand || '-' || v_model),
                                 '[^a-z0-9]+', '-', 'g'), '-');

  select m.id into v_id
  from public.motorcycles m
  where (lower(m.brand) = lower(v_brand) and lower(m.model) = lower(v_model))
     or m.slug = v_slug
  order by m.is_active desc, m.created_at
  limit 1;
  if v_id is not null then
    return v_id;
  end if;

  if p_engine_cc_min is null and p_engine_cc_max is null then
    p_engine_cc_min := lower(v_range);
    p_engine_cc_max := upper(v_range) - 1;
  end if;

  insert into public.motorcycles
    (brand, model, slug, min_year, is_active, collected_since,
     olx_search, standvirtual_search, engine_cc_min, engine_cc_max)
  values
    (v_brand, v_model, v_slug, extract(year from now())::integer, false, null,
     nullif(btrim(p_olx_search), ''),
     nullif(btrim(p_standvirtual_search), ''),
     p_engine_cc_min, p_engine_cc_max)
  returning id into v_id;
  return v_id;
end;
$$;

--
-- Name: bike_value_ready(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bike_value_ready(p_motorcycle_id uuid, p_year integer) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.motorcycles m
    where m.id = p_motorcycle_id
      and m.is_active
      and m.min_year <= greatest(p_year - 3, 1990)
      and exists (select 1 from public.collector_runs r
                  where r.started_at >= m.collected_since
                    and r.status in ('ok', 'partial'))
  )
$$;

