$$;

--
-- Name: duplicate_similarity(integer, integer, numeric, numeric, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.duplicate_similarity(p_mileage_a integer, p_mileage_b integer, p_price_a numeric, p_price_b numeric, p_location_a text, p_location_b text, p_description_a text, p_description_b text, p_seller_a text, p_seller_b text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select
    -- mileage
    case
      when p_mileage_a is null or p_mileage_b is null then 0
      when p_mileage_a = p_mileage_b
        then case when p_mileage_a >= 500 then 40 else 10 end
      when abs(p_mileage_a - p_mileage_b) <= 100
           and greatest(p_mileage_a, p_mileage_b) >= 500 then 20
      else 0
    end
    -- price
    + case
      when p_price_a is null or p_price_b is null
           or greatest(p_price_a, p_price_b) <= 0 then 0
      when abs(p_price_a - p_price_b) / greatest(p_price_a, p_price_b) <= 0.03 then 20
      when abs(p_price_a - p_price_b) / greatest(p_price_a, p_price_b) <= 0.10 then 10
      else 0
    end
    -- location
    + case
      when nullif(btrim(p_location_a), '') is not null
           and lower(btrim(p_location_a)) = lower(btrim(p_location_b)) then 20
      else 0
    end
    -- description text, only when both are long enough to compare
    + case
      when char_length(coalesce(p_description_a, '')) < 40
           or char_length(coalesce(p_description_b, '')) < 40 then 0
      when extensions.similarity(lower(p_description_a), lower(p_description_b)) >= 0.8 then 30
      when extensions.similarity(lower(p_description_a), lower(p_description_b)) >= 0.6 then 15
      else 0
    end
    -- dealer name
    + case
      when nullif(btrim(p_seller_a), '') is not null
           and lower(btrim(p_seller_a)) = lower(btrim(p_seller_b)) then 10
      else 0
    end
$$;

--
-- Name: ended_at_expiry(timestamp with time zone, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ended_at_expiry(p_published timestamp with time zone, p_refreshed timestamp with time zone, p_last_seen timestamp with time zone) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select coalesce(bool_or(
           r.days >= 28
           and r.days - 30 * round(r.days / 30) between -2 and 1
         ), false)
  from (
    select extract(epoch from p_last_seen - d) / 86400 as days
    from unnest(array[p_published, p_refreshed]) d
    where d is not null and d <= p_last_seen
  ) r
$$;

--
-- Name: engine_range_from_name(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.engine_range_from_name(p_model text) RETURNS int4range
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  select case when n between 50 and 2500
              then int4range(round(n * 0.9)::integer, round(n * 1.1)::integer, '[]')
         end
  from (select (regexp_match(btrim(p_model), '(?:^|\s)(\d{2,4})\s*(?:cc)?$', 'i'))[1]::integer as n) x;
$_$;

--
-- Name: ensure_model_searches(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_model_searches() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  new.olx_search := coalesce(nullif(btrim(new.olx_search), ''),
    public.catalog_search_url('olx', new.brand, new.model));
  new.standvirtual_search := coalesce(nullif(btrim(new.standvirtual_search), ''),
    public.catalog_search_url('standvirtual', new.brand, new.model));
  return new;
end;
$$;

--
-- Name: exit_kind(public.listings); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.exit_kind(l public.listings) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select case
    when l.status not in ('removed', 'sold') then null
    when l.status = 'sold' or l.sold_marked_at is not null then 'sold_in_text'
    when exists (
      select 1 from public.listings r where r.relisted_from = l.id
    ) then 'relisted'
    when exists (
      select 1 from public.listings o
      where o.id <> l.id
        and o.status in ('active', 'price_changed')
        and (o.duplicate_of = l.id
             or o.id = l.duplicate_of
             or o.duplicate_of = l.duplicate_of)
    ) then 'still_listed'
    when l.seller_type <> 'dealer'
     and public.ended_at_expiry(l.published_at, l.site_refreshed_at, l.last_seen_at)
    then 'expired'
    when l.last_seen_at - l.first_seen_at < interval '1 hour' then 'seen_once'
    else 'likely_sold'
  end
$$;

--
-- Name: exit_price(uuid, integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.exit_price(p_motorcycle_id uuid, p_year integer, p_mileage integer DEFAULT NULL::integer, p_except uuid DEFAULT NULL::uuid) RETURNS TABLE(gone_count integer, median_price numeric)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  with excepted as (
    select e.id, e.duplicate_of
    from public.listings e
    where e.id = p_except
  ),
  gone as (
    select c.year, c.mileage, c.price,
           p_year is not null and abs(p_year - c.year) <= 3 as near
    from public.listings c
    where c.motorcycle_id = p_motorcycle_id
      and c.status in ('removed', 'sold')
      and c.last_seen_at >= now() - interval '90 days'
      and c.duplicate_of is null
      and c.price >= 300
      and (p_year is null or c.year is not null)
      and (p_mileage is null or c.mileage is not null)
      and public.exit_kind(c) in ('sold_in_text', 'likely_sold')
      and not exists (
        select 1 from excepted x
        where c.id = x.id or c.id = x.duplicate_of
      )
  ),
  chosen as (
    select g.*
    from gone g
    where g.near
       or (select count(*) from gone n where n.near) < 5
  ),
  adjusted as (
    select ch.price * public.age_mileage_factor(
             p_year - ch.year,
             p_mileage - ch.mileage,
             coalesce(d.per_year, 0.04),
             coalesce(d.per_1000km, 0.002)
           ) as price
    from chosen ch
    left join public.model_depreciation d on d.motorcycle_id = p_motorcycle_id
  )
  select
    count(*)::integer,
    round((percentile_cont(0.5) within group (order by price))::numeric, 2)
  from adjusted;
$$;

--
-- Name: expected_mileage(integer, integer, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expected_mileage(p_year integer, p_km_per_year integer DEFAULT 5000, p_reference numeric DEFAULT public.decimal_year()) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select case when p_year is null then null
              else round(greatest(p_reference - (p_year + 0.5), 1) * p_km_per_year)::integer
         end
$$;

--
-- Name: expire_bike_value_models(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expire_bike_value_models() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_model uuid;
  v_count integer := 0;
begin
  for v_model in
    select m.id
    from public.motorcycles m
    where m.is_active
      and exists (select 1 from public.bike_value_requests r
                  where r.motorcycle_id = m.id)
      and not exists (
        select 1 from public.bike_value_requests r
        where r.motorcycle_id = m.id
          and r.requested_at > now()
              - pg_catalog.make_interval(days => public.bike_value_request_days()))
  loop
    perform public.refresh_collected_model(v_model);
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;

--
-- Name: fact_edit_signals(integer, boolean, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fact_edit_signals(p_mileage integer, p_mileage_from_text boolean, p_mileage_max_seen integer, p_year integer, p_year_first_seen integer) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select array_remove(array[
    case when p_mileage is not null and not coalesce(p_mileage_from_text, false)
              and p_mileage_max_seen - p_mileage >= 1000
         then 'mileage_lowered' end,
    case when p_year > p_year_first_seen then 'year_raised' end
  ], null)
$$;

--
-- Name: favourites_shared_with_me(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.favourites_shared_with_me() RETURNS TABLE(owner_id uuid, owner_email text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select s.owner_id, u.email::text
  from public.favourite_shares s
  join auth.users u on u.id = s.owner_id
  where s.viewer_id = auth.uid()
  order by u.email
$$;

--
-- Name: fill_listing_colour(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fill_listing_colour() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  new.colour := coalesce(public.colour_code(new.site_colour),
                         public.colour_in_text(new.variant, new.description));
  return new;
end;
$$;

--
-- Name: fill_mileage_from_text(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fill_mileage_from_text() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.mileage is null or new.mileage_from_text then
    new.mileage := public.mileage_in_text(new.description);
    new.mileage_from_text := new.mileage is not null;
  end if;
  return new;
end;
$$;

--
-- Name: fill_sold_marked(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fill_sold_marked() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if public.sold_in_text(new.variant, new.description) then
    new.sold_marked_at := coalesce(new.sold_marked_at, now());
  else
    new.sold_marked_at := null;
  end if;
  return new;
end;
$$;

--
-- Name: fill_text_signals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fill_text_signals() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'INSERT'
     or new.text_signals is null or new.text_extras is null
     or new.variant is distinct from old.variant
     or new.description is distinct from old.description then
    new.text_signals := public.description_signals(new.variant, new.description);
    new.text_extras := public.listing_extras(new.variant, new.description);
  end if;
  return new;
end;
$$;

