-- Name: finish_photo_exams(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finish_photo_exams(p_listings uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
