    AS $$
declare
  n integer;
begin
  update public.listings
  set photos_examined_all_at = now(),
      photo_exam_requested_at = null
  where id = any (p_listings)
    and photo_exam_requested_at is not null;
  get diagnostics n = row_count;
  return n;
