--
-- Name: legalisation_cap(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.legalisation_cap(p_reasons text[]) RETURNS smallint
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case when p_reasons && array['not_legalised', 'not_legalised_outside_eu']
              then 79::smallint end
$$;

--
-- Name: legalisation_cost(text[], integer, numeric, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.legalisation_cost(p_reasons text[], p_engine_cc integer, p_price numeric, p_year integer, p_mileage integer) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select case
    when not coalesce(p_reasons && array['not_legalised', 'not_legalised_outside_eu'], false)
      then 0
    else public.motorcycle_isv(p_engine_cc) + 95 + 100 + 30
      + coalesce(p_price, 0) * case
          when 'not_legalised_outside_eu' = any(p_reasons) then 0.30
          when p_year >= extract(year from current_date)::integer - 1
           and p_mileage <= 6000 then 0.23
          else 0
        end
  end
$$;

--
-- Name: legalisation_status(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.legalisation_status(p_variant text, p_description text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  with t as (
    -- "não precisa de legalizar" says the opposite.
    select regexp_replace(lower(concat_ws(' ', p_variant, p_description)),
             '(\mn[ãa]o|\mnunca)\s+(precis|necessit)\w*\s+(\w+\s+){0,2}?legaliz\w*',
             ' ', 'g') as d
  ),
  found as (
    select d,
      -- Still to do.
      d ~ ('\mn[ãa]o\s+(est[áa]\s+|se\s+encontra\s+|foi\s+)?legalizad'
           '|\m(por|para|a)\s+legalizar\M'
           '|\mfalta(m|r)?\s+([^\s.!?;]+\s+){0,8}?legaliz'
           '|\mproceder\s+[àa]\s+legaliza'
           '|(precis|necessit|carece)\w*\s+(de\s+)?(ser\s+)?legaliz'
           '|\mlegaliza[çc][ãa]o\s+([^\s.!?;]+\s+){0,3}?'
           '(a\s+cargo|por\s+conta|por\s+fazer|pendente|n[ãa]o\s+inclu)')
        as pending,
      -- A foreign registration.
      d ~ ('\mmatr[íi]cula\s+(\w+\s+)?(inglesa|brit[âa]nica|espanhola|francesa'
           '|alem[ãa]|italiana|holandesa|belga|su[íi][çc]a|luxemburguesa'
           '|estrangeira|do\s+reino\s+unido|\muk\M|\mgb\M)'
           '|\mmatriculad[ao]\s+(em|n[ao]s?)\s+(inglaterra|reino\s+unido|espanha'
           '|fran[çc]a|alemanha|it[áa]lia|holanda|b[ée]lgica|su[íi][çc]a'
           '|luxemburgo|estrangeiro|\muk\M)')
        as foreign_plate,
      -- Legalised already ("já legalizada", "matrícula portuguesa").
      regexp_replace(d, '\mn[ãa]o\s+(est[áa]\s+|se\s+encontra\s+|foi\s+)?legalizad\w*',
                     ' ', 'g')
        ~ ('\mlegalizad[ao]\M|\mmatr[íi]cula\s+(portuguesa|nacional)'
           '|\mmatr[íi]cula\s+pt\M')
        as done
    from t
  )
  select case
    when not (pending or (foreign_plate and not done)) then null
    when d ~ ('\m(matr[íi]cula|matriculad[ao]|importad[ao]|vind[ao]|veio|proveniente|origem)'
              '\s+([^\s.!?;]+\s+){0,3}?'
              '(ingl|brit[âa]n|reino\s+unido|\muk\M|\mgb\M|su[íi][çc]|noruega|esc[óo]c)')
      then 'not_legalised_outside_eu'
    else 'not_legalised'
  end
  from found
$$;

--
-- Name: likes_colour(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.likes_colour(p_user uuid, p_motorcycle_id uuid, p_colour text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select exists (select 1 from public.user_models u
                 where u.user_id = p_user
                   and u.motorcycle_id = p_motorcycle_id
                   and p_colour = any (u.colours))
$$;

--
-- Name: listing_extras(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listing_extras(p_variant text, p_description text) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  with t as (
    select regexp_replace(
             lower(coalesce(p_variant, '') || ' ' || coalesce(p_description, '')),
             '\msem\s+(o\s+|a\s+|os\s+|as\s+)?\w+', ' ', 'g'
           ) as text
  ),
  rules(code, pattern) as (
    values
      ('quickshifter', '(quick\s*-?\s*shift|\mshifter\M|blipper)'),
      ('exhaust',
        '(akrapovi|arkapovi|dominator|linha\s+(de\s+escape\s+)?completa|termignoni|sc[\s-]?project|yoshimura|leovince|\mmivv\M|\marrow\M'
        '|\mgpr\M|bodis|\mzard\M|giannelli|\mremus\M|two\s+brothers|austin\s+racing'
        '|hp\s+corse|\mixil\M|scorpion|ponteiras?\s+(de\s+escape|desportiv)'
        '|escape\s+(\w+\s+)?(desportivo|racing|completo|de\s+competi|after\s*-?\s*market))'),
      ('luggage',
        '(top\s*-?\s*case|\mmalas\M|malas?\s+laterais|alforges|\mba[uú]\M'
        '|malas?\s+(de\s+)?dep[oó]sito|sacos?\s+de\s+dep[oó]sito|tank\s*-?\s*bag'
        '|top\s*-?\s*box|\mmala\s+(\w+\s+){0,3}(shad|givi|kappa|traseira|lateral|top)|porta[\s-]*bagagens?|grelha\s+traseira|suporte\s+(de\s+|para\s+)?(malas?|top))'),
      ('heated_grips',
        '(punhos\s+(aquecidos|t[eé]rmicos)|manoplas\s+aquecidas'
        '|aquecimento\s+(de|dos|nos)\s+punhos)'),
      ('protection',
        '(crash\s*-?\s*(pads?|bars?)|\msliders?\M|cogumelos|\mprote[cç][oõ]es\M'
        '|barras?\s+de\s+prote|tank\s*-?\s*pad|grelha\s+(de\s+|do\s+)?radiador'
        -- engine covers and protectors by their makers
        '|gb\s*-?\s*racing|tampas?\s+(de\s+|do\s+)?(motor|embraiagem|alternador)\s+(\w+\s+)?(carbono|prote|racing)'
        '|prote[cç][cç]?[aã]o\s+(de\s+|do\s+|da\s+|dos\s+|das\s+)?(motor|quadro|c[aá]rter|radiador|dep[oó]sito|punhos?|m[aã]os|manetes?|corrente|farol|escape|peseiras?|calcanhar(es)?|pedais)'
        '|(protetor(es)?|prote[cç][oõ]es)\s+laterais'
        '|protetor(es)?\s+(de\s+|do\s+|da\s+|dos\s+|das\s+)?(motor|quadro|c[aá]rter|radiador|dep[oó]sito|punhos?|m[aã]os|manetes?|corrente|farol|escape|peseiras?|calcanhar(es)?|pedais))'),
      ('new_tyres',
        '(pneus?\s+(\w+\s+){0,2}(novos?|recentes?)\M|pneus?\s+(mudad|trocad|substitu[ií]d)'
        '|pneus?\s+(foram|s[aã]o)\s+(novos|mudad|trocad|substitu[ií]d)'
        '|(mudou|trocou|colocou|meteu)\s+pneus)'),
      ('tail_tidy',
        '(suporte\s+curto|(suporte|porta)[\s-]*(de\s+|da\s+)?matr[ií]culas?\s+(\w+\s+)?(curt|desportiv|regul[aá]v|lightech|rizoma|evotech|puig|barracuda|highsider|gilles|bonamici|r\s*&\s*g\M)'
        '|matr[ií]cula\s+curta|eliminador\s+(de\s+|do\s+)?guarda[\s-]*lamas|tail\s*-?\s*tidy)'),
      ('screen',
        '((bolha|viseira|para[\s-]*brisas?|ecr[aã]|vidro)\s+(\w+\s+){0,2}'
        '(fumad|fum[eê]|escurecid|escur|desportiv|alt[ao]|touring|racing|puig|ermax|\mmra\M|givi|kappa)'
        -- a deflector is an added screen ("defletor frontal", "fly screen")
        '|\mde(f|fl)e[cç]?tor(es)?\M|fly\s*-?\s*screen)'),
      ('levers',
        -- also misspelt ("manteres curtas")
        '(\mmane?te?r?e?s?\s+(\w+\s+)?(ajust[aá]ve|regul[aá]ve|curt|desportiv|articulad|rizoma|puig|\mcnc\M|gilles|lightech|bonamici|evotech|\mlsl\M|valter))'),
      ('mirrors',
        '(espelhos?\s+(\w+\s+)?(de\s+|na\s+)?(ponta|punho|bar[\s-]*end|rizoma)'
        '|retrovisores?\s+(\w+\s+)?(de\s+|na\s+)?(ponta|bar[\s-]*end|rizoma))'),
      ('phone_mount',
        '(suporte\s+(de\s+|para\s+)?(telem[oó]vel|smartphone|telefone|gps)'
        '|quad\s*-?\s*lock|carregador\s+usb|tomada\s+usb|\musb\M)'),
      ('alarm', '(\malarme\M|mapit|localizador)'),
      ('steering_damper', '(amortecedor\s+de\s+dire[cç]|steering\s+damper)'),
      ('centre_stand', 'descanso\s+central'),
      ('cruise_control',
        '(cruise\s*-?\s*control|controlo\s+de\s+velocidade|velocidade\s+de\s+cruzeiro)'),
      ('suspension',
        '([öo]hlins|k[\s-]?tech|wilbers|hyperpro|matris|andreani'
        '|suspens[aã]o\s+(\w+\s+)?(afinad|melhorad|upgrade|revista))'),
      ('led_indicators', '((piscas?|indicadores)\s+(\w+\s+)?led\M)'),
      ('passenger_grips',
        '((suporte|pegas?|apoios?|al[cç]as?)\s+(\w+\s+){0,2}m[aã]os\s+(\w+\s+){0,2}pendura'
        '|(pegas?|al[cç]as?)\s+(\w+\s+){0,2}pendura|grab\s*-?\s*rails?)'),
      -- The parts taken off come with the bike, so it can go back to stock.
      ('original_parts',
        '((partes|pe[cç]as)\s+(\w+\s+)?(de\s+origem|originais)'
        '|(inclui|acompanha|entrego|entrega|oferece|vai\s+com|com)\s+(\w+\s+){0,3}(de\s+origem|originais)'
        '|\morigina(l|is)\s+(inclu|tamb[eé]m|acompanha)'
        -- "segue todo o material original", "vem com o vidro original"
        '|material\s+(\w+\s+)?(original|de\s+origem)'
        '|\m(vem|segue|seguem|vai|v[aã]o)\s+(\w+\s+){0,4}(original|originais|de\s+origem)\M)')
  )
  select coalesce(array_agg(r.code order by r.code), '{}'::text[])
  from rules r, t
  where t.text ~ r.pattern
$$;

--
-- Name: listing_for_ad(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listing_for_ad(p_url text) RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select l.id
  from public.listings l
  where l.source = public.ad_link_source(p_url)
    and substring(l.url from '-(ID[0-9A-Za-z]+)\.html') = public.ad_link_code(p_url)
  order by (l.status = 'active') desc, l.last_seen_at desc
  limit 1
$$;

--
-- Name: listing_matches_search(uuid, integer, numeric, integer, text, public.seller_type, uuid, integer, numeric, integer, text, public.seller_type); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listing_matches_search(l_motorcycle_id uuid, l_year integer, l_price numeric, l_mileage integer, l_location text, l_seller_type public.seller_type, s_motorcycle_id uuid, s_min_year integer, s_max_price numeric, s_max_mileage integer, s_location text, s_seller_type public.seller_type) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select coalesce(
    (s_motorcycle_id is null or l_motorcycle_id = s_motorcycle_id)
    and (s_min_year is null or l_year >= s_min_year)
    and (s_max_price is null or (l_price >= 300 and l_price <= s_max_price))
    and (s_max_mileage is null or l_mileage <= s_max_mileage)
    and (s_location is null
         or strpos(lower(coalesce(l_location, '')), lower(s_location)) > 0)
    and (s_seller_type is null or l_seller_type = s_seller_type),
    false
  )
$$;

--
-- Name: listing_time_to_sale(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listing_time_to_sale(p_listing_id uuid) RETURNS TABLE(band text, gone_count integer, live_count integer, days_listed integer, typical_days integer, remaining_days integer)
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  l public.listings;
  my_band text;
  age numeric;
  use_band boolean;
  days numeric[];
  gone boolean[];
begin
  select * into l from public.listings where id = p_listing_id;
  if l.id is null or l.motorcycle_id is null then
    return;
  end if;

  age := greatest(0, extract(epoch from
           now() - coalesce(l.published_at, l.first_seen_at)) / 86400);
  my_band := public.market_band(l.last_pct_below_market);

  -- A gone ad's band is where it was when last scored. A gone ad one run
  -- saw tells nothing of how long ads last (N.93).
  with sample as (
    select greatest(0, extract(epoch from
             case when o.status in ('removed', 'sold') then o.last_seen_at
                  else now() end
             - coalesce(o.published_at, o.first_seen_at)) / 86400) as days,
           o.status in ('removed', 'sold') as gone,
           public.market_band(o.last_pct_below_market) as band
    from public.listings o
    where o.motorcycle_id = l.motorcycle_id
      and o.duplicate_of is null
      and o.id <> l.id
      and o.id is distinct from l.duplicate_of
      and not (o.status in ('removed', 'sold')
               and o.last_seen_at - o.first_seen_at < interval '1 hour')
  ),
  chosen as (
    select s.*,
           my_band is not null
           and count(*) filter (where s.gone and s.band = my_band)
               over () >= 5 as by_band
    from sample s
  )
  select bool_or(c.by_band),
         array_agg(c.days), array_agg(c.gone),
         count(*) filter (where c.gone), count(*) filter (where not c.gone)
  into use_band, days, gone, gone_count, live_count
  from chosen c
  where not c.by_band or c.band = my_band;

  band := case when use_band then my_band end;
  gone_count := coalesce(gone_count, 0);
  live_count := coalesce(live_count, 0);
  days_listed := floor(age)::integer;
  if gone_count >= 5 then
    typical_days := ceil(public.median_days_remaining(days, gone, 0))::integer;
    if l.status in ('active', 'price_changed') then
      -- At least a day (greatest would also turn a null into 1).
      remaining_days := ceil(
        public.median_days_remaining(days, gone, age))::integer;
      if remaining_days < 1 then
        remaining_days := 1;
      end if;
    end if;
  end if;
  return next;
end;
$$;

--
-- Name: listings_awaiting_photo_exam(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listings_awaiting_photo_exam(p_limit integer DEFAULT 20, p_photos integer DEFAULT 30) RETURNS TABLE(id uuid, images text[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select l.id, l.images[1:p_photos]
  from public.listings l
  join public.motorcycles m on m.id = l.motorcycle_id and m.is_active
  where l.photo_exam_requested_at is not null
    and l.photos_examined_all_at is null
    and l.status in ('active', 'price_changed')
    and cardinality(l.images) > 0
  order by l.photo_exam_requested_at, l.id
  limit p_limit
$$;

--
-- Name: listings_missing_details(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listings_missing_details(p_source text, p_limit integer DEFAULT NULL::integer) RETURNS TABLE(source_listing_id text, url text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select l.source_listing_id, l.url
  from public.listings l
  where l.source = p_source
    and l.photos_read_at is null
    and l.motorcycle_id is not null
    and l.duplicate_of is null
    and l.status in ('active', 'price_changed')
  order by
    l.details_failed_at nulls first,
    l.details_checked_at nulls first,
    case
      when exists (select 1 from public.listing_favourites f where f.listing_id = l.id) then 0
      when exists (select 1 from public.alerts a
                   where a.listing_id = l.id and a.dismissed_at is null) then 1
      else 2
    end,
    l.deal_score desc nulls first,
    l.first_seen_at desc,
    l.id
  limit p_limit;
$$;

--
-- Name: listings_missing_photo_checks(integer, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listings_missing_photo_checks(p_limit integer DEFAULT 200, p_photos integer DEFAULT 3, p_examine boolean DEFAULT false) RETURNS TABLE(id uuid, images text[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select l.id, l.images[1:p_photos]
  from public.listings l
  join public.motorcycles m on m.id = l.motorcycle_id and m.is_active
  where l.status in ('active', 'price_changed')
    and (l.photos_hashed_at is null
         or (p_examine and l.photos_examined_at is null))
    and cardinality(l.images) > 0
    and (l.source <> 'standvirtual'
         or l.photos_read_at is not null
         or l.details_failed_at is not null)
  order by l.photos_hashed_at is null desc, l.duplicate_of is null desc,
           l.first_seen_at desc, l.id
  limit p_limit
$$;

--
-- Name: listings_missing_photo_hashes(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listings_missing_photo_hashes(p_limit integer DEFAULT 200, p_photos integer DEFAULT 3) RETURNS TABLE(id uuid, images text[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select l.id, l.images[1:p_photos]
  from public.listings l
  join public.motorcycles m on m.id = l.motorcycle_id and m.is_active
  where l.status in ('active', 'price_changed')
    and l.photos_hashed_at is null
    and cardinality(l.images) > 0
    and (l.source <> 'standvirtual'
         or l.photos_read_at is not null
         or l.details_failed_at is not null)
  order by l.duplicate_of is null desc, l.first_seen_at desc, l.id
  limit p_limit
$$;

