--
-- Name: mark_duplicates(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_duplicates(p_threshold integer DEFAULT 70) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  n integer;
begin
  with recursive live as (
    select * from public.listings
    where status in ('active', 'price_changed')
  ),
  pairs as (
    select
      b.id as dup_id,
      a.id as original_id,
      a.first_seen_at as original_seen,
      case
        when coalesce(abs(a.mileage - b.mileage) <= 1000, true)
         and exists (select 1 from public.listing_photo_matches m
                     where m.listing_id = a.id and m.other_id = b.id)
          then 100
        else public.duplicate_similarity(
          a.mileage, b.mileage, a.price, b.price, a.location, b.location,
          a.description, b.description, a.seller_name, b.seller_name
        )
      end as score
    from live a
    join live b
      on a.motorcycle_id = b.motorcycle_id
     and a.year = b.year
     and (a.first_seen_at, a.id) < (b.first_seen_at, b.id)
    -- a dealer's identical new bikes are separate stock, not duplicates
    where not (a.source = b.source
               and coalesce(a.mileage, 0) < 500
               and coalesce(b.mileage, 0) < 500)
  ),
  best as (
    select distinct on (dup_id) dup_id, original_id, score
    from pairs
    where score >= p_threshold
    order by dup_id, original_seen, original_id
  ),
  -- Chains: if C duplicates B and B duplicates A, C points at A. An
  -- original is always seen before its copy, so a chain never loops.
  chain (dup_id, root_id, score, depth) as (
    select dup_id, original_id, score, 0 from best
    union all
    select c.dup_id, b.original_id, c.score, c.depth + 1
    from chain c
    join best b on b.dup_id = c.root_id
  ),
  resolved as (
    select distinct on (dup_id) dup_id, root_id, score
    from chain
    order by dup_id, depth desc
  ),
  wanted as (
    select l.id, r.root_id, r.score
    from live l
    left join resolved r on r.dup_id = l.id
  ),
  changed as (
    update public.listings l
    set duplicate_of = w.root_id,
        duplicate_score = w.score
    from wanted w
    where l.id = w.id
      and (l.duplicate_of, l.duplicate_score)
          is distinct from (w.root_id, w.score)
    returning 1
  )
  select count(*) into n from best;

  -- A gone listing keeps its mark; one that points at a listing that is
  -- now itself a copy follows it to the first.
  for i in 1..5 loop
    update public.listings c
    set duplicate_of = p.duplicate_of
    from public.listings p
    where c.duplicate_of = p.id and p.duplicate_of is not null;
    exit when not found;
  end loop;

  perform public.mark_relists(p_threshold);

  return n;
end;
$$;

--
-- Name: mark_listings_seen(text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_listings_seen(p_source text, p_ids text[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  n integer;
begin
  update public.listings
  set last_seen_at    = now(),
      last_checked_at = now(),
      status = case
        when status = 'removed' then 'active'::public.listing_status
        else status
      end
  where source = p_source
    and source_listing_id = any (p_ids);

  get diagnostics n = row_count;
  return n;
end;
$$;

--
-- Name: mark_recall_noticed(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_recall_noticed(p_user uuid, p_case text) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with marked as (
    insert into public.recall_notices (user_id, case_number)
    values (p_user, p_case)
    on conflict do nothing
    returning 1)
  select exists (select 1 from marked)
$$;

--
-- Name: mark_relists(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_relists(p_threshold integer DEFAULT 70, p_max_gap_days integer DEFAULT 90) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  n integer;
begin
  with pairs as (
    select distinct on (b.id)
      b.id,
      a.id as previous_id,
      coalesce(
        a.relisted_since,
        least(a.published_at, a.first_seen_at)
      ) as since,
      a.price
    from public.listings b
    join public.listings a
      on a.motorcycle_id = b.motorcycle_id
     and a.year = b.year
     and a.status in ('removed', 'sold')
     and a.last_seen_at <= b.first_seen_at
     and a.last_seen_at > b.first_seen_at - make_interval(days => p_max_gap_days)
    where b.status in ('active', 'price_changed')
      -- a dealer's identical new bikes are separate stock
      and not (a.source = b.source
               and coalesce(a.mileage, 0) < 500
               and coalesce(b.mileage, 0) < 500)
      and ((coalesce(abs(a.mileage - b.mileage) <= 1000, true)
            and exists (select 1 from public.listing_photo_matches m
                        where m.listing_id = a.id and m.other_id = b.id))
           or public.duplicate_similarity(
                a.mileage, b.mileage, a.price, b.price, a.location, b.location,
                a.description, b.description, a.seller_name, b.seller_name
              ) >= p_threshold)
    order by b.id, a.last_seen_at desc, a.id
  ),
  wanted as (
    select b.id, p.previous_id, p.since, p.price
    from public.listings b
    left join pairs p on p.id = b.id
    where b.status in ('active', 'price_changed')
  ),
  changed as (
    update public.listings l
    set relisted_from  = w.previous_id,
        relisted_since = w.since,
        relisted_price = w.price
    from wanted w
    where l.id = w.id
      and (l.relisted_from, l.relisted_since, l.relisted_price)
          is distinct from (w.previous_id, w.since, w.price)
    returning 1
  )
  select count(*) into n from pairs;

  return n;
end;
$$;

--
-- Name: mark_removed_listings(text, text[], numeric, text[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_removed_listings(p_source text, p_seen_ids text[], p_max_fraction numeric DEFAULT 0.5, p_search_keys text[] DEFAULT NULL::text[], p_include_unkeyed boolean DEFAULT true) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  live_count    integer;
  missing_count integer;
begin
  if p_seen_ids is null or cardinality(p_seen_ids) = 0 then
    raise exception
      'Refusing to mark listings as removed: the import contains no listings.';
  end if;

  select count(*),
         count(*) filter (where l.source_listing_id <> all (p_seen_ids))
  into live_count, missing_count
  from public.listings l
  where l.source = p_source
    and l.status in ('active', 'price_changed')
    and public.in_removal_scope(l, p_search_keys, p_include_unkeyed);

  if live_count > 0
     and missing_count::numeric / live_count > p_max_fraction then
    raise exception
      'Refusing to remove % of % live listings (limit % percent). Check the file, or use --force.',
      missing_count, live_count, round(p_max_fraction * 100);
  end if;

  update public.listings l
  set status = 'removed',
      last_checked_at = now()
  where l.source = p_source
    and l.status in ('active', 'price_changed')
    and public.in_removal_scope(l, p_search_keys, p_include_unkeyed)
    and l.source_listing_id <> all (p_seen_ids);

  return missing_count;
end;
$$;

--
-- Name: mark_visit_reminded(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_visit_reminded(p_user uuid, p_listing uuid, p_visit_at timestamp with time zone) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with marked as (
    update public.listing_favourites f
    set visit_reminded_at = now()
    where f.user_id = p_user
      and f.listing_id = p_listing
      and f.visit_at = p_visit_at
      and f.visit_reminded_at is null
    returning 1)
  select exists (select 1 from marked)
$$;

--
-- Name: market_band(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_band(p_pct_below numeric) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when p_pct_below is null then null
    when p_pct_below >= 5 then 'below'
    when p_pct_below <= -5 then 'above'
    else 'near'
  end
$$;

--
-- Name: market_position(public.listings); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_position(l public.listings) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when l.price >= 300
     and coalesce((l.score_breakdown ->> 'market_listing_count')::integer, 0) >= 3
    then round(
      case
        when l.score_breakdown ->> 'legalisation_cost' is not null
         and l.score_breakdown ->> 'pct_below_legalised_value' is not null
        then (l.score_breakdown ->> 'pct_below_legalised_value')::numeric
        when l.score_breakdown ->> 'damage_allowance' is not null
         and l.score_breakdown ->> 'pct_below_damaged_value' is not null
        then (l.score_breakdown ->> 'pct_below_damaged_value')::numeric
        else (l.score_breakdown ->> 'pct_below_market')::numeric
      end, 1)
  end
$$;

--
-- Name: median_days_remaining(numeric[], boolean[], numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.median_days_remaining(p_days numeric[], p_gone boolean[], p_age numeric) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  at_risk bigint;
  survival numeric := 1;
  at_age numeric;
  r record;
begin
  select count(*) into at_risk
  from unnest(p_days, p_gone) u(days, gone)
  where u.days is not null;

  for r in
    select u.days,
           count(*) filter (where u.gone) as left_then,
           count(*) as ended_then
    from unnest(p_days, p_gone) u(days, gone)
    where u.days is not null
    group by u.days
    order by u.days
  loop
    -- The survival just before this time is the one at the ad's age.
    if r.days > p_age and at_age is null then
      at_age := survival;
    end if;
    survival := survival * (1 - r.left_then::numeric / at_risk);
    at_risk := at_risk - r.ended_then;
    -- (With a margin for the rounding of thirds and the like.)
    if at_age is not null and r.left_then > 0
       and survival <= at_age / 2 + 1e-9 then
      return r.days - p_age;
    end if;
  end loop;
  return null;
end;
$$;

--
-- Name: mentions_accident(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mentions_accident(p_description text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  with t as (
    select regexp_replace(
             regexp_replace(
               regexp_replace(
                 lower(coalesce(p_description, '')),
                 '(\msem\M|\mnunca\M|\mn[ãa]o\M|\mnem\M|\mnenhu\w*|livre\s+de|\mzero\M|isent[ao]\s+de)'
                 '\s+([^\s.,!?;]+\s+){0,3}?(sinistr\w*|acident\w*|danos?|batid[ao]s?|bateu'
                 '|quedas?|ca[ií]u|ca[ií]d[ao]s?|toques?|tomb\w*|embat\w*|colis\w*|colidiu'
                 '|pancadas?|derrap\w*|ao\s+ch[ãa]o)',
                 ' ', 'g'),
               -- Insurance wording: "seguro contra todos os riscos e sinistros".
               'seguro\s+.{0,40}sinistr\w*', ' ', 'g'),
             -- Prices fall too: "o preço caiu", "baixou".
             '(pre[çc]o|valor)\s+(\w+\s+){0,2}?ca[ií]u', ' ', 'g') as d
  )
  select d ~ '(sinistr|acident|batid[ao]|\mbateu\M|\mca[ií]u\M|\mca[ií]d[ao]\M|\mtomb(ou|ad[ao])\M'
             '|\membat|colis[ãa]o|colidiu|ao\s+ch[ãa]o|derrap'
             -- "danos de queda"
             '|\mdanos?\s+(de|da|por)\s+(uma\s+)?queda)'
      or d ~ '\m(teve|sofreu|deu|levou|apanhou)\s+(um|uma)\s+(\w+\s+)?'
             '(toque|toquezinho|pancada|queda|tombo|batida|embate)'
  from t
$$;

--
-- Name: mileage_in_text(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mileage_in_text(p_description text) RETURNS integer
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  d      constant text := lower(coalesce(p_description, ''));
  -- "25,673" groups thousands with a comma (a decimal has 1-2 digits).
  num    constant text :=
    '(\d{1,3}(?:[.\s]\d{3})+|\d{1,3}(?:,\d{3})+(?!\d)|\d+(?:[.,]\d{1,2})?)';
  -- A unit not followed by "/h", "por mês", "de autonomia" or a verb
  -- ("com 15.000 km troquei a corrente").
  unit   constant text :=
    '\s*(mil)?\s*/?\s*(?:km|kms|quil[oó]metros)\M'
    '(?!\s*(?:/|por\M|p/|h\M|de\s+autonomia'
    '|tro[cq]u|mud[aeoá]|substitu|instal|coloc|coloqu|mont[aeo]'
    '|f[ie]z\M|foi\M|foram\M|lev[eo]|meti\M|pus\M))';
  other  constant text :=
    '(pneu|revis|[óo]leo|corrente|\mkit|garantia|autonomia|pr[oó]xim|troc'
    '|mud[aeo]|embraiag|pastilh|trav[õoã]|filtro|\mvelas?\M|\mcada\M'
    '|[uú]ltim|manuten|servi[çc]o|feit[ao]|bateria|viage|percurso'
    '|tro[cq]u|substitu|instal|coloc|coloqu|\mmont(?:ei|ou|ad|ar|ag)|\mcompr[aeo]'
    '|\mfiz\M|inspe[çc]|check|\mipo\M|afina|lubrific'
    '|\m(?:aos|dos|os|nos|[àa]s|das|at[eé]|h[aá]|faz)\s*$'
    '|(?:menos|mais)\s+de\s*$)';
  leads  constant text :=
    '(?:\mtem|\mcom|apenas|\ms[oó]|c/|quilometragem|marca)\s*$';
  r      record;
  n      numeric;
  led    integer[] := '{}'::integer[];
  plain  integer[] := '{}'::integer[];
begin
  -- "... com 12.000 km": the clause before the number, the number, "mil".
  for r in
    select x.m
    from regexp_matches(d, '([^.,;:!?\n]*?)\m' || num || unit, 'g') as x(m)
  loop
    continue when right(r.m[1], 50) ~ other;
    n := public.mileage_number(r.m[2], r.m[3] is not null);
    continue when n is null;
    if r.m[1] ~ leads then led := led || n::integer;
    else plain := plain || n::integer;
    end if;
  end loop;

  -- "Quilometragem: 12000", "Kms: 12.000", also without the colon
  -- ("Ano 2025 Km 7.500"), where a year is not the mileage ("12.000 km
  -- 2019").
  for r in
    select x.m
    from regexp_matches(d,
      '(?:quilometragem\s*([:=-])?|(?:quil[oó]metros|\mkms?)\s*([:=-])?)\s*'
      || num || '\s*(mil)?\M', 'g') as x(m)
  loop
    continue when r.m[1] is null and r.m[2] is null
      and r.m[3] ~ '^(19|20)\d\d$';
    n := public.mileage_number(r.m[3], r.m[4] is not null);
    continue when n is null;
    led := led || n::integer;
  end loop;

  if cardinality(led) > 0 then
    plain := led;
  end if;
  if (select count(distinct v) from unnest(plain) v) = 1 then
    return plain[1];
  end if;
  return null;
end;
$_$;

--
-- Name: mileage_number(text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mileage_number(p_number text, p_thousands boolean) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  select v
  from (
    select case
      when p_thousands then
        replace(regexp_replace(p_number, '\s', '', 'g'), ',', '.')::numeric
        * 1000
      when p_number ~ '^\d+[.,]\d{1,2}$' then null
      else regexp_replace(p_number, '[.,\s]', '', 'g')::numeric
    end as v
  ) x
  where v <= 300000
$_$;

--
-- Name: mileage_score(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mileage_score(p_mileage integer, p_max_km integer DEFAULT 20000) RETURNS smallint
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when p_mileage is null or p_mileage < 0 or p_max_km <= 0 then null
    else greatest(0, least(100, round(
      100 * (1 - p_mileage::numeric / p_max_km)
    )))::smallint
  end
$$;

--
-- Name: mileage_use_score(integer, integer, integer, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mileage_use_score(p_mileage integer, p_year integer, p_km_per_year integer DEFAULT 5000, p_reference numeric DEFAULT public.decimal_year()) RETURNS smallint
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select case
    when p_mileage is null or p_mileage < 0 then null
    when p_year is null then public.mileage_score(p_mileage)
    else (select greatest(0, least(100, round(case
                when r <= 0.5 then 100
                when r <= 1.5 then 100 - (r - 0.5) * 50
                else 50 - (r - 1.5) * 50
              end)))::smallint
          from (select p_mileage::numeric
                       / public.expected_mileage(p_year, p_km_per_year, p_reference) as r) x)
  end
$$;

--
-- Name: model_recalls(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.model_recalls(p_motorcycle_id uuid, p_year integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'case_number', r.case_number,
           'published_on', r.published_on,
           'name', concat_ws(' ', nullif(r.product, 'Motorcycle'), r.name),
           'production_dates', r.production_dates,
           'from_year', r.from_year,
           'to_year', r.to_year,
           'recall_code', r.recall_code,
           'alert_url', r.alert_url,
           'danger_en', r.danger_en,
           'danger_pt', r.danger_pt,
           'country_en', r.country_en,
           'country_pt', r.country_pt,
           'applies', p_year is null or r.from_year is null
                      or p_year between r.from_year and r.to_year + 1)
         order by r.published_on desc, r.case_number), '[]'::jsonb)
  from public.motorcycles m
  join public.vehicle_recalls r on public.recall_is_of_model(r, m)
  where m.id = p_motorcycle_id
$$;

--
-- Name: model_specs_to_check(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.model_specs_to_check(p_days integer DEFAULT 30) RETURNS TABLE(id uuid, brand text, model text, aliases text[], excluded_words text[], engine_cc_min smallint, engine_cc_max smallint, power_kw numeric, torque_nm numeric, weight_kg smallint, seat_height_mm smallint, tank_l numeric, fuel_l_per_100km numeric, front_tyre text, rear_tyre text, cylinders smallint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select m.id, m.brand, m.model, m.aliases, m.excluded_words,
         m.engine_cc_min, m.engine_cc_max,
         m.power_kw, m.torque_nm, m.weight_kg, m.seat_height_mm, m.tank_l,
         m.fuel_l_per_100km, m.front_tyre, m.rear_tyre, m.cylinders
  from public.motorcycles m
  where m.specs_checked_at is null
     or (m.specs_checked_at < now() - make_interval(days => p_days)
         and (m.power_kw is null or m.torque_nm is null or m.weight_kg is null
              or m.seat_height_mm is null or m.tank_l is null
              or m.fuel_l_per_100km is null or m.front_tyre is null
              or m.rear_tyre is null or m.cylinders is null))
  order by m.brand, m.model;
$$;

--
-- Name: motorcycle_isv(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.motorcycle_isv(p_engine_cc integer) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when p_engine_cc is null then 245.14
    when p_engine_cc <= 119 then 0
    when p_engine_cc <= 250 then 73.78
    when p_engine_cc <= 350 then 91.63
    when p_engine_cc <= 500 then 122.57
    when p_engine_cc <= 750 then 184.45
    else 245.14
  end
$$;

--
-- Name: my_colour(public.listings); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_colour(l public.listings) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select public.likes_colour((select auth.uid()), l.motorcycle_id, l.colour)
$$;

--
-- Name: motorcycles; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.motorcycles (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    brand text NOT NULL,
    model text NOT NULL,
    slug text NOT NULL,
    min_year smallint NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    new_price_reference numeric(10,2),
    new_price_checked_at date,
    aliases text[] DEFAULT '{}'::text[] NOT NULL,
    excluded_words text[] DEFAULT '{}'::text[] NOT NULL,
    engine_cc_min smallint,
    engine_cc_max smallint,
    olx_search text,
    standvirtual_search text,
    collected_since timestamp with time zone DEFAULT now(),
    new_price_from_ads numeric(10,2),
    new_price_ad_count smallint,
    front_tyre text,
    rear_tyre text,
    cylinders smallint,
    service_interval_km integer,
    valve_check_km integer,
    power_kw numeric(5,1),
    fuel_l_per_100km numeric(3,1),
    torque_nm numeric(4,1),
    weight_kg smallint,
    seat_height_mm smallint,
    tank_l numeric(3,1),
    specs_checked_at timestamp with time zone,
    CONSTRAINT motorcycles_both_source_searches CHECK (((olx_search IS NOT NULL) AND (standvirtual_search IS NOT NULL))),
    CONSTRAINT motorcycles_cylinders CHECK (((cylinders >= 1) AND (cylinders <= 6))),
    CONSTRAINT motorcycles_engine_cc_max_check CHECK ((engine_cc_max > 0)),
    CONSTRAINT motorcycles_engine_cc_min_check CHECK ((engine_cc_min > 0)),
    CONSTRAINT motorcycles_engine_cc_range CHECK (((engine_cc_min IS NULL) OR (engine_cc_max IS NULL) OR (engine_cc_min <= engine_cc_max))),
    CONSTRAINT motorcycles_front_tyre_size CHECK ((front_tyre ~ '^[0-9]{2,3}/[0-9]{2}-[0-9]{2}$'::text)),
    CONSTRAINT motorcycles_fuel_consumption CHECK (((fuel_l_per_100km >= (1)::numeric) AND (fuel_l_per_100km <= (15)::numeric))),
    CONSTRAINT motorcycles_new_price_reference_check CHECK ((new_price_reference >= (0)::numeric)),
    CONSTRAINT motorcycles_olx_search_check CHECK ((olx_search ~~ 'https://www.olx.pt/carros-motos-e-barcos/motociclos-scooters/%'::text)),
    CONSTRAINT motorcycles_power_kw CHECK (((power_kw > (0)::numeric) AND (power_kw <= (250)::numeric))),
    CONSTRAINT motorcycles_rear_tyre_size CHECK ((rear_tyre ~ '^[0-9]{2,3}/[0-9]{2}-[0-9]{2}$'::text)),
    CONSTRAINT motorcycles_seat_height_mm CHECK (((seat_height_mm >= 500) AND (seat_height_mm <= 1100))),
    CONSTRAINT motorcycles_service_interval CHECK (((service_interval_km >= 1000) AND (service_interval_km <= 50000))),
    CONSTRAINT motorcycles_standvirtual_search_check CHECK ((standvirtual_search ~~ 'https://www.standvirtual.com/motos/%'::text)),
    CONSTRAINT motorcycles_tank_l CHECK (((tank_l >= (3)::numeric) AND (tank_l <= (40)::numeric))),
    CONSTRAINT motorcycles_torque_nm CHECK (((torque_nm > (0)::numeric) AND (torque_nm <= (300)::numeric))),
    CONSTRAINT motorcycles_valve_check CHECK (((valve_check_km >= 5000) AND (valve_check_km <= 100000))),
    CONSTRAINT motorcycles_weight_kg CHECK (((weight_kg >= 60) AND (weight_kg <= 450)))
);

