--
-- Name: my_colours(public.motorcycles); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_colours(m public.motorcycles) RETURNS text[]
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select coalesce(
    (select u.colours from public.user_models u
     where u.user_id = (select auth.uid()) and u.motorcycle_id = m.id),
    '{}')
$$;

--
-- Name: my_favourite_share(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_favourite_share() RETURNS TABLE(viewer_email text, code text, code_expires_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select u.email::text, s.code,
         case when s.code_expires_at > now() then s.code_expires_at end
  from public.favourite_shares s
  left join auth.users u on u.id = s.viewer_id
  where s.owner_id = auth.uid()
$$;

--
-- Name: my_min_year(public.motorcycles); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_min_year(m public.motorcycles) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select coalesce(
    (select u.min_year from public.user_models u
     where u.user_id = auth.uid() and u.motorcycle_id = m.id),
    m.min_year)
$$;

