-- Name: my_photo_marks(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_photo_marks(p_listing uuid) RETURNS TABLE(photo integer, problem boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select m.photo::integer, m.problem
  from public.photo_marks m
  where m.user_id = auth.uid() and m.listing_id = p_listing and public.is_admin()
  order by m.photo
$$;

--
-- Name: needs_repair(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.needs_repair(p_description text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  with parts(p) as (
    select '(pisca|espelho|retrovisor|manete|carenage|farol|farolim|guarda-?lamas'
           '|suporte|ponteira|tampa|banco|pl[áa]stic|pe[çc]a|quadro|jante|para-?brisas?'
           '|bolha|pedal|poisa-?p[ée]s|sele[ct]?or|punho|escape|radiador|forquilha'
           '|guiador|dep[óo]sito|painel|matr[íi]cula|tanque|motor|embraiagem|caixa'
           -- brakes: "necessita de travão traseiro e disco"
           '|trav[ãaõo]|discos?\M)'
  ),
  t as (
    select regexp_replace(
             regexp_replace(
               regexp_replace(
                 regexp_replace(
                   lower(coalesce(p_description, '')),
                   -- An electric start is not a broken part.
                   '(bot[ãa]o|ponto|sistema)\s+de\s+partida'
                   '|partida\s+(el[ée]c?trica|a\s+frio|autom[áa]tica)',
                   ' ', 'g'),
                 -- "não precisa de nada", "sem nada partido", "não falta nada".
                 '(\msem\M|\mnunca\M|\mn[ãa]o\M|\mnem\M|\mnenhu\w*|\mnada\M|livre\s+de|\mzero\M'
                 '|isent[ao]\s+de)\s+([^\s.,!?;]+\s+){0,3}?'
                 '(precis\w*|necessit\w*|carece\w*|partid\w*|amolgad\w*|danific\w*|danos?'
                 '|avari\w*|falt\w*|empenad\w*|repara\w*)',
                 ' ', 'g'),
               -- "ideal para quem precisa de uma mota", "se precisar de".
               '\m(quem|se)\s+(\w+\s+)?(precis|necessit)\w*', ' ', 'g'),
             -- "precisa de carta A2", "necessita de licença".
             '(precis|necessit)\w*\s+(\w+\s+){0,2}?(carta|licen[çc]a|habilita[çc][ãa]o|categoria)',
             ' ', 'g') as d
  )
  select d ~ ('(precis|necessit|carece)\w*\s+([^\s.,!?;]+\s+){0,3}?'
              '(repar|arranj|substitu|pintur|bate-?chapa|' || p || ')')
      or d ~ '\mpara\s+(reparar|arranjar|recuperar|pe[çc]as)\M'
      or d ~ '\mavari'
      or d ~ '\mn[ãa]o\s+(pega|trabalha|arranca)\M'
      or d ~ '(amolgad|empenad|danificad)'
      or d ~ '\mdanos?\s+(n[oa]s?|em)\M'
      or d ~ ('\mfalta(m|r)?\s+([^\s.,!?;]+\s+){0,3}?\m' || p)
      or d ~ ('\m' || p || '\w*\s+([^\s.,!?;]+\s+){0,2}?em\s+falta')
      or d ~ ('\m' || p || '\w*\s+([^\s.,!?;]+\s+){0,3}?partid[ao]s?\M')
      or d ~ '\m(est[áa]|ficou|vem|veio)\s+(\w+\s+)?partid[ao]s?\M'
  from t, parts
$$;

--
-- Name: new_bike_ad(integer, integer, numeric, public.seller_type, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.new_bike_ad(p_year integer, p_mileage integer, p_price numeric, p_seller_type public.seller_type, p_signals text[]) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select p_seller_type = 'dealer'
     and p_price >= 300
     and p_year >= extract(year from now() at time zone 'Europe/Lisbon')::int - 1
     and p_mileage is not null and p_mileage <= 100
     and not coalesce(p_signals && array['possible_accident', 'needs_repair',
                                         'cosmetic_damage', 'not_legalised',
                                         'not_legalised_outside_eu'], false)
$$;

--
-- Name: olx_copies_to_skip(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.olx_copies_to_skip(p_copies jsonb) RETURNS SETOF text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select c.key
  from jsonb_each_text(coalesce(p_copies, '{}'::jsonb)) as c
  where c.value in (
      select substring(l.url from '-(ID[0-9A-Za-z]+)\.html')
      from public.listings l
      where l.source = 'standvirtual'
    )
    and not exists (
      select 1
      from public.listings o
      where o.source = 'olx'
        and o.source_listing_id = c.key
    );
$$;

--
-- Name: owned_bike_mileage(integer, date, integer, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.owned_bike_mileage(p_mileage_at_purchase integer, p_bought_on date, p_km_per_year integer, p_day date) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when p_mileage_at_purchase is null then null
    when p_day <= p_bought_on then p_mileage_at_purchase
    else (round((p_mileage_at_purchase
                 + p_km_per_year * (p_day - p_bought_on) / 365.25) / 100) * 100)::integer
  end
$$;

--
-- Name: owned_bike_value_min_comparables(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.owned_bike_value_min_comparables() RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$ select 3 $$;

--
-- Name: owner_tracks(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.owner_tracks(p_user uuid, p_motorcycle_id uuid, p_year integer) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when auth.uid() is not null and p_user is distinct from auth.uid() then false
    when (select coalesce(u.is_anonymous, false) from auth.users u where u.id = p_user)
    then public.collected(p_motorcycle_id, p_year)
    else public.user_tracks(p_user, p_motorcycle_id, p_year)
  end
$$;

--
-- Name: pending_notifications(integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pending_notifications(p_limit integer DEFAULT 200, p_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(alert_id uuid, user_id uuid, listing_id uuid, type public.alert_type, old_price numeric, new_price numeric, brand text, model text, year integer, mileage integer, price numeric, deal_score smallint, location text, url text, created_at timestamp with time zone, my_colour boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select a.id, a.user_id, l.id, a.type, a.old_price::numeric, a.new_price::numeric,
         l.brand::text, l.model::text, l.year::integer, l.mileage::integer,
         l.price::numeric, l.deal_score::smallint, l.location::text, l.url::text,
         a.created_at,
         public.likes_colour(a.user_id, l.motorcycle_id, l.colour)
  from public.alerts a
  join public.listings l on l.id = a.listing_id
  join auth.users u on u.id = a.user_id
  where a.notified_at is null
    and not coalesce(u.is_anonymous, false)
    and (p_at is null or not public.account_quiet_at(a.user_id, p_at))
  order by a.created_at
  limit p_limit
$$;

--
-- Name: pending_recall_notices(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pending_recall_notices(p_at timestamp with time zone) RETURNS TABLE(user_id uuid, case_number text, bike_id uuid, listing_id uuid, brand text, model text, year integer, recall_name text, recall_code text, danger_en text, danger_pt text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with bikes as (
    select b.user_id, b.id as bike_id, b.listing_id, b.motorcycle_id,
           b.year::integer as year, b.created_at, 0 as rank
    from public.owned_bikes b
    union all
    select f.user_id, null, f.listing_id, l.motorcycle_id,
           l.year, f.created_at, 1
    from public.listing_favourites f
    join public.listings l on l.id = f.listing_id
    where l.status in ('active', 'price_changed')
      and l.motorcycle_id is not null
  )
  select distinct on (k.user_id, r.case_number)
         k.user_id, r.case_number, k.bike_id, k.listing_id,
         m.brand, m.model, k.year,
         concat_ws(' ', nullif(r.product, 'Motorcycle'), r.name),
         r.recall_code, r.danger_en, r.danger_pt
  from bikes k
  join auth.users u on u.id = k.user_id and not coalesce(u.is_anonymous, false)
  join public.motorcycles m on m.id = k.motorcycle_id
  join public.vehicle_recalls r on public.recall_is_of_model(r, m)
  where r.stored_at > k.created_at
    and r.published_on >= (p_at at time zone 'Europe/Lisbon')::date
                          - public.recall_notice_days()
    and (k.year is null or r.from_year is null
         or k.year between r.from_year and r.to_year + 1)
    and not exists (select 1 from public.recall_notices n
                    where n.user_id = k.user_id and n.case_number = r.case_number)
    and not public.account_quiet_at(k.user_id, p_at)
  order by k.user_id, r.case_number, k.rank, k.created_at desc
$$;

--
-- Name: pending_visit_reminders(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pending_visit_reminders(p_at timestamp with time zone) RETURNS TABLE(user_id uuid, listing_id uuid, visit_at timestamp with time zone, visit_day integer, visit_time text, brand text, model text, year integer, price numeric, location text, is_live boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select f.user_id, f.listing_id, f.visit_at,
         ((f.visit_at at time zone 'Europe/Lisbon')::date
           - (p_at at time zone 'Europe/Lisbon')::date)::integer,
         to_char(f.visit_at at time zone 'Europe/Lisbon', 'HH24:MI'),
         l.brand, l.model, l.year, l.price, l.location,
         l.status in ('active', 'price_changed')
  from public.listing_favourites f
  join public.listings l on l.id = f.listing_id
  join auth.users u on u.id = f.user_id and not coalesce(u.is_anonymous, false)
  where f.visit_reminded_at is null
    and f.visit_at > p_at
    and f.visit_at <= p_at + interval '24 hours'
    and not public.account_quiet_at(f.user_id, p_at)
  order by f.visit_at, f.user_id, f.listing_id
$$;

--
-- Name: photo_exam_answers(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.photo_exam_answers(p_listings uuid[]) RETURNS TABLE(user_id uuid, listing_id uuid, brand text, model text, year integer, hints integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select r.user_id, l.id, l.brand::text, l.model::text, l.year::integer,
         (select count(distinct h ->> 'code')::integer
          from jsonb_array_elements(l.photo_hints) h)
  from public.photo_exam_requests r
  join public.listings l on l.id = r.listing_id
  join auth.users u on u.id = r.user_id
  where r.listing_id = any (p_listings)
    and l.photos_examined_all_at is not null
    and not coalesce(u.is_anonymous, false)
  order by r.requested_at, r.user_id
$$;

--
-- Name: photo_hint_codes(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.photo_hint_codes(p_photos jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(
    jsonb_build_object('code', code, 'photo', photo, 'p', p)
    order by p desc, code
  ), '[]')
  from (
    select distinct on (s.key)
      s.key as code,
      (e ->> 'photo')::integer as photo,
      round((s.value #>> '{}')::numeric, 2) as p
    from jsonb_array_elements(coalesce(p_photos, '[]')) e
    cross join lateral jsonb_each(coalesce(e -> 'scores', '{}')) s
    where s.key not in ('ok', 'other')
      and jsonb_typeof(s.value) = 'number'
      and (s.value #>> '{}')::numeric >= 0.5
    order by s.key, (s.value #>> '{}')::numeric desc, (e ->> 'photo')::integer
  ) best
$$;

--
-- Name: photo_learned_share(text, bytea); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.photo_learned_share(p_model text, p_features bytea) RETURNS double precision
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select 1 / (1 + exp(-least(greatest(
    c.bias + sum(
      (case when get_byte(p_features, i) > 127 then get_byte(p_features, i) - 256
            else get_byte(p_features, i) end)::double precision / 127
      * c.weights[i + 1]), -50), 50)))
  from public.photo_classifiers c
  cross join generate_series(0, length(p_features) - 1) i
  where c.model = p_model and cardinality(c.weights) = length(p_features)
  group by c.bias
$$;

--
-- Name: photo_training_set(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.photo_training_set(p_model text) RETURNS TABLE(features text, problem boolean, marks_key text, trained_key text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with marked as (
    select f.features, bool_or(m.problem) as problem, max(m.marked_at) as marked_at
    from public.photo_marks m
    join public.app_admins a on a.user_id = m.user_id
    join public.listing_photo_features f
      on f.listing_id = m.listing_id and f.photo = m.photo
    where f.model = p_model and f.features is not null
    group by f.listing_id, f.photo, f.features
  ),
  state as (
    select count(*) || '@' || coalesce(max(marked_at)::text, '') as k from marked
  )
  select encode(marked.features, 'base64'), marked.problem, state.k,
         (select c.marks_key from public.photo_classifiers c where c.model = p_model)
  from state left join marked on true
$$;

--
-- Name: place_district(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.place_district(p_location text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select p.district from public.places p
  where p.key = public.place_key(p_location)
$$;

--
-- Name: place_key(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.place_key(p_name text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select nullif(btrim(regexp_replace(
    regexp_replace(
      translate(
        split_part(regexp_replace(lower(p_name), '\(.*?\)', ' ', 'g'), ',', 1),
        'áàâãäéèêëíìîïóòôõöúùûüçñ',
        'aaaaaeeeeiiiiooooouuuucn'),
      '[-''.]', ' ', 'g'),
    '\s+', ' ', 'g')), '')
$$;

--
-- Name: power_version(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.power_version(p_variant text, p_description text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  with t as (
    select regexp_replace(
             regexp_replace(
               regexp_replace(
                 lower(concat_ws(' ', p_variant, p_description)),
                 -- Something that could be done, not what was done:
                 -- "pode ser limitada a 35 kW", "fácil de deslimitar",
                 -- "ideal para limitar", "kit A2 incluído".
                 '(pode(ndo)?\s+(ser|ficar|se)|possibilidade\s+de(\s+ser)?'
                 '|f[áa]cil(mente)?(\s+de)?|op[çc][ãa]o\s+de|preparad[ao]\s+para(\s+ser)?'
                 '|\mpara)\s+(\w+\s+){0,2}?(des)?(limit|bloque|restring)\w*'
                 '(\s+(a|para|em|aos?)\s+(35\s*kw|a2|\d+\s*(cv|hp)))?',
                 ' ', 'g'),
               '(des)?limit[áa]vel(\s+(a|para|em|aos?)\s+(35\s*kw|a2|\d+\s*(cv|hp)))?'
               '|kit\s+(de\s+)?(limita[çc][ãa]o|a2)\s+(inclu[íi]d[ao]|oferta|em\s+oferta|dispon[íi]vel|opcional)',
               ' ', 'g'),
             -- "não está limitada": said of a full-power bike.
             'n[ãa]o\s+(est[áa]\s+|[ée]\s+|vem\s+)?limitad[ao]',
             ' ', 'g') as d
  )
  select case
    when d ~ '(deslimit|desbloque|desrestring)\w*'
      or d ~ '(limita[çc][ãa]o|kit(\s+a2)?|restri[çc][ãa]o)\s+(foi\s+|j[áa]\s+)?(removid|retirad|tirad)'
      or d ~ '(estava|esteve|era|vinha)\s+(\w+\s+){0,2}?limitad'
      then 'a2_unlocked'
    when d ~ '(vers[ãa]o\s+full|full\s+power|pot[êe]ncia\s+(total|m[áa]xima|completa))'
      then null
    when d ~ 'limitad[ao]'
      or d ~ '\m35\s*kw'
      or d ~ 'vers[ãa]o\s+(a2|35)'
      or d ~ '\ma2\s+(limitad|kit|montad)'
      or d ~ 'kit\s+(de\s+)?(limita[çc][ãa]o|a2)\s+(montad|instalad|colocad)'
      then 'a2_limited'
  end
  from t
$$;

--
-- Name: price_drop_outlook(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.price_drop_outlook(p_listing_id uuid, p_days integer DEFAULT 30) RETURNS TABLE(sample integer, dropped integer, gone integer, unchanged integer, median_drop numeric)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  with me as (
    select l.id, l.motorcycle_id, l.duplicate_of,
           greatest(interval '0', now() - l.first_seen_at) as age
    from public.listings l
    where l.id = p_listing_id
      and l.motorcycle_id is not null
      and l.status in ('active', 'price_changed')
      and l.price >= 300
  ),
  windows as (
    select o.id,
           o.status in ('removed', 'sold') as is_gone,
           case when o.status in ('removed', 'sold') then o.last_seen_at
                else now() end as ended,
           o.first_seen_at + me.age as starts,
           o.first_seen_at + me.age + make_interval(days => p_days) as ends
    from me
    join public.listings o on o.motorcycle_id = me.motorcycle_id
    where o.duplicate_of is null
      and o.id <> me.id
      and o.id is distinct from me.duplicate_of
      -- A gone ad one run saw (N.93).
      and not (o.status in ('removed', 'sold')
               and o.last_seen_at - o.first_seen_at < interval '1 hour')
  ),
  followed as (
    select w.*,
           (select h.price
            from public.listing_price_history h
            where h.listing_id = w.id and h.observed_at <= w.starts
            order by h.observed_at desc
            limit 1) as start_price
    from windows w
    where w.ended >= w.starts
      and (w.is_gone or now() >= w.ends)
  ),
  outcomes as (
    select f.start_price,
           f.is_gone and f.ended <= f.ends as left_market,
           (select min(h.price)
            from public.listing_price_history h
            where h.listing_id = f.id
              and h.observed_at > f.starts
              and h.observed_at <= f.ends
              and h.price >= 300
              and h.price <= f.start_price * 0.99) as low
    from followed f
    where f.start_price >= 300
  )
  select count(*)::integer,
         count(*) filter (where o.low is not null)::integer,
         count(*) filter (where o.low is null and o.left_market)::integer,
         count(*) filter (where o.low is null and not o.left_market)::integer,
         round((percentile_cont(0.5) within group (
           order by (1 - o.low / o.start_price) * 100)
           filter (where o.low is not null))::numeric, 1)
  from outcomes o
  where exists (select 1 from me)
$$;

--
-- Name: price_score(numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.price_score(p_price numeric, p_market_price numeric, p_points_per_percent numeric DEFAULT 5) RETURNS smallint
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when p_price is null or p_market_price is null or p_market_price <= 0
      then null
    else greatest(0, least(100, round(
      50 + (p_market_price - p_price) / p_market_price * 100 * p_points_per_percent
    )))::smallint
  end
$$;

--
-- Name: prune_anonymous_users(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prune_anonymous_users(p_idle_days integer DEFAULT 30) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_deleted integer;
begin
  delete from auth.users u
  where u.is_anonymous
    and u.created_at < pg_catalog.now() - pg_catalog.make_interval(days => p_idle_days)
    and not exists (
      select 1 from auth.sessions s
      where s.user_id = u.id
        -- greatest ignores nulls: the latest of the dates there are.
        and greatest(s.created_at, s.updated_at, s.refreshed_at at time zone 'utc')
            >= pg_catalog.now() - pg_catalog.make_interval(days => p_idle_days));
  get diagnostics v_deleted = row_count;
  return v_deleted;
end;
$$;

--
-- Name: prune_unfollowed_listings(bigint, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prune_unfollowed_listings(p_limit_bytes bigint DEFAULT ((400 * 1024) * 1024), p_min_days integer DEFAULT 30) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_bytes bigint := pg_catalog.pg_database_size(pg_catalog.current_database());
  v_deleted integer;
begin
  if v_bytes < p_limit_bytes then
    return 0;
  end if;

  delete from public.listings l
  where l.status in ('removed', 'sold')
    and l.source in ('olx', 'standvirtual')
    and l.last_checked_at < now() - pg_catalog.make_interval(days => p_min_days)
    and not exists (select 1 from public.motorcycles m
                    where m.id = l.motorcycle_id and m.is_active)
    and not exists (select 1 from public.listing_favourites f where f.listing_id = l.id)
    and not exists (select 1 from public.alerts a where a.listing_id = l.id)
    and not exists (select 1 from public.listings o
                    where o.relisted_from = l.id or o.duplicate_of = l.id);
  get diagnostics v_deleted = row_count;

  if v_deleted > 0 then
    perform public.send_telegram(pg_catalog.format(
      '🧹 A base de dados chegou a %s MB (limite gratuito: 500 MB): foram apagados %s anúncios antigos de modelos que ninguém acompanha.',
      v_bytes / (1024 * 1024), v_deleted));
  end if;
  return v_deleted;
end;
$$;

--
-- Name: push_endpoint_allowed(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.push_endpoint_allowed(p_endpoint text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select coalesce(lower(p_endpoint) ~ (
    '^https://([a-z0-9-]+\.)*'
    '(fcm\.googleapis\.com|android\.googleapis\.com|push\.apple\.com'
    '|push\.services\.mozilla\.com|notify\.windows\.com)(:443)?/'), false)
$$;

--
-- Name: push_keys(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.push_keys() RETURNS TABLE(public_key text, private_key text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select c.public_key, s.decrypted_secret
  from public.push_config c
  join vault.decrypted_secrets s on s.name = 'vapid_private_key'
$$;

--
-- Name: recalculate_deal_scores(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalculate_deal_scores() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET jit TO 'off'
    AS $$
declare
  n integer;
begin
  perform public.refresh_new_prices_from_ads();

  with dealers as (
    select d.dealer_key, d.bikes,
           public.dealer_score(d.bikes, d.relisted, d.sharp_changes,
                               d.missing_mileage, d.repeated) as score
    from public.dealer_reliability d
  ),
  scored as materialized (
    select
      l.id,
      l.price,
      ps.market_price,
      public.damage_allowance(rs.reasons) as allowance,
      -- Not yet legalised in Portugal (N.52): what that costs comes off.
      public.legalisation_cost(
        rs.reasons, coalesce(m.engine_cc_max, m.engine_cc_min),
        case when l.price >= 300 then l.price else ps.market_price end,
        l.year, l.mileage) as legalisation,
      ps.pct_below_market,
      ps.listing_count,
      -- Nearly new (2 years or less from mid-year, at most half the normal
      -- mileage): also compared with the price of a new one (N.51).
      case when l.year is not null
            and public.decimal_year() - (l.year + 0.5) <= 2
            and public.mileage_use_score(l.mileage, l.year) = 100
           then coalesce(m.new_price_from_ads, m.new_price_reference)
      end as new_price,
      coalesce(public.mileage_use_score(l.mileage, l.year),
               -- Hidden mileage: no better than an average-to-high one.
               case when l.year is not null then 50 end) as m_score,
      public.age_score(l.year)        as y_score,
      rs.risk_score,
      rs.reasons,
      coalesce(l.text_extras,
               public.listing_extras(l.variant, l.description)) as extras,
      dl.score as seller_score,
      dl.bikes as dealer_bikes
    from public.listings l
    join public.motorcycles m on m.id = l.motorcycle_id
    left join public.listing_price_scores ps on ps.listing_id = l.id
    left join public.listing_risk_scores  rs on rs.listing_id = l.id
    left join dealers dl
      on l.seller_type = 'dealer'
     and dl.dealer_key = lower(btrim(l.seller_name))
    where l.status in ('active', 'price_changed')
      and l.duplicate_of is null
      and l.motorcycle_id is not null
  ),
  combined as (
    select
      s.id,
      s.risk_score,
      s.allowance,
      -- least ignores nulls: the lower of the caps that apply.
      coalesce(least(c.deal_score,
                     public.damage_cap(s.reasons),
                     public.legalisation_cap(s.reasons)),
               c.deal_score) as deal_score,
      c.breakdown || jsonb_build_object(
        'market_price',         s.market_price,
        'pct_below_market',     s.pct_below_market,
        'market_listing_count', s.listing_count,
        'risk_reasons',         to_jsonb(coalesce(s.reasons, '{}'::text[])),
        'extras',               to_jsonb(s.extras),
        'valued_extras',        to_jsonb(public.valued_extras(s.extras)),
        'dealer_bikes',         s.dealer_bikes,
        'damage_allowance',     nullif(s.allowance, 0),
        'damaged_value',
          case when s.allowance > 0 then round(s.damaged_value) end,
        'pct_below_damaged_value',
          case when s.allowance > 0 and s.damaged_value > 0
               then round((s.damaged_value - s.price) / s.damaged_value * 100, 1)
          end,
        'new_price',            round(s.new_price),
        'pct_below_new',
          case when s.new_price > 0
               then round((s.new_price - s.price) / s.new_price * 100, 1)
          end,
        'legalisation_cost',
          case when s.legalisation > 0 then round(s.legalisation) end,
        'legalised_value',
          case when s.legalisation > 0 then round(s.compared_value) end,
        'pct_below_legalised_value',
          case when s.legalisation > 0 and s.compared_value > 0
               then round((s.compared_value - s.price) / s.compared_value * 100, 1)
          end,
        'capped_for_legalisation',
          coalesce(c.deal_score > public.legalisation_cap(s.reasons), false),
        'price_from_new',       coalesce(s.new_score > s.market_score
                                         or (s.market_score is null
                                             and s.new_score is not null), false),
        'capped_for_damage',
          coalesce(c.deal_score > public.damage_cap(s.reasons), false)
      ) as breakdown
    from (
      -- The price is scored against the value of the bike with its damage,
      -- so a damaged bike well below that still ranks high.
      -- A nearly new bike takes the better of that and its price against a
      -- new one's (not a damaged one: the damage is unseen; nor one still
      -- to be legalised).
      select s1.*,
             case when s1.new_score > s1.market_score
                    or s1.market_score is null
                  then coalesce(s1.new_score, s1.market_score)
                  else s1.market_score
             end as price_score
      from (
        select s0.*,
               s0.market_price * (1 - s0.allowance) as damaged_value,
               case when s0.listing_count >= 3
                    then public.price_score(s0.price,
                           greatest(s0.compared_value, 1), 2.5)
               end as market_score,
               case when s0.allowance = 0 and s0.legalisation = 0
                     and s0.new_price > 0
                    then public.price_score(s0.price, s0.new_price, 2.5)
               end as new_score
        from (
          -- The value the price is compared with: the estimate less a
          -- repair allowance and what legalising costs.
          select sc.*,
                 sc.market_price * (1 - sc.allowance) - sc.legalisation
                   as compared_value
          from scored sc
        ) s0
      ) s1
    ) s
    cross join lateral public.combine_deal_score(
      s.price_score, s.m_score, s.y_score, s.risk_score,
      cardinality(public.valued_extras(s.extras)), s.seller_score
    ) c
  )
  update public.listings l
  set deal_score      = c.deal_score,
      risk_score      = c.risk_score,
      score_breakdown = c.breakdown,
      scored_at       = now()
  from combined c
  where l.id = c.id;

  get diagnostics n = row_count;

  update public.listings
  set deal_score = null, risk_score = null,
      score_breakdown = null, scored_at = null
  where (status not in ('active', 'price_changed')
         or duplicate_of is not null
         or motorcycle_id is null)
    and (deal_score is not null or risk_score is not null
         or score_breakdown is not null);

  return n;
end;
$$;

--
-- Name: vehicle_recalls; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.vehicle_recalls (
    case_number text NOT NULL,
    report text NOT NULL,
    published_on date NOT NULL,
    brand text,
    product text,
    name text,
    model_type text,
    production_dates text,
    from_year smallint,
    to_year smallint,
    recall_code text,
    alert_url text,
    danger_en text,
    danger_pt text,
    country_en text,
    country_pt text,
    match_keys text[] DEFAULT '{}'::text[] NOT NULL,
    stored_at timestamp with time zone DEFAULT now(),
    CONSTRAINT vehicle_recalls_alert_url_check CHECK ((alert_url ~~ 'https://ec.europa.eu/%'::text))
);

--
-- Name: recall_is_of_model(public.vehicle_recalls, public.motorcycles); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recall_is_of_model(p_recall public.vehicle_recalls, p_bike public.motorcycles) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select position(lower(p_bike.brand) in lower(concat_ws(' ', p_recall.brand, p_recall.product, p_recall.name))) > 0
     and exists (
       select
       from unnest(array_prepend(p_bike.model, p_bike.aliases)) as n(name)
       cross join lateral (select public.recall_model_key(n.name) as k) key
       where length(key.k) >= 2
         and (key.k = any(p_recall.match_keys) or key.k || 'a' = any(p_recall.match_keys))
     )
$$;

--
-- Name: recall_match_keys(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recall_match_keys(p_text text) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  with words as (
    select w, n
    from unnest(regexp_split_to_array(lower(coalesce(p_text, '')), '[^[:alnum:]]+'))
           with ordinality as t(w, n)
    where w <> ''
  ), numbered as (
    select w, row_number() over (order by n) as i from words
  )
  select coalesce(array_agg(distinct k), '{}')
  from (
    select a.w as k from numbered a
    union all
    select a.w || b.w from numbered a join numbered b on b.i = a.i + 1
    union all
    select a.w || b.w || c.w
    from numbered a
    join numbered b on b.i = a.i + 1
    join numbered c on c.i = a.i + 2
  ) keys
$$;

--
-- Name: recall_model_key(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recall_model_key(p_name text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select nullif(lower(regexp_replace(coalesce(p_name, ''), '[^[:alnum:]]', '', 'g')), '')
$$;

--
-- Name: recall_notice_days(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recall_notice_days() RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$ select 60 $$;

--
-- Name: recall_years(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recall_years(p_text text, OUT from_year smallint, OUT to_year smallint) RETURNS record
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select min(y)::smallint, max(y)::smallint
  from (
    select m[1]::integer as y
    from regexp_matches(coalesce(p_text, ''), '(?:^|[^0-9])((?:19[5-9]|20[0-9])[0-9])(?![0-9])', 'g') m
  ) years
$$;

