--
-- Name: record_api_usage(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_api_usage(p_service text, p_requests integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_today date := (now() at time zone 'Europe/Lisbon')::date;
begin
  if p_requests is null or p_requests <= 0 then
    return;
  end if;
  insert into public.api_usage (service, day, requests)
  values (p_service, v_today, p_requests)
  on conflict (service, day) do update
    set requests = public.api_usage.requests + excluded.requests;
  delete from public.api_usage where day < v_today - interval '13 months';
end;
$$;

--
-- Name: record_initial_price(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_initial_price() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.price is not null then
    insert into public.listing_price_history (listing_id, price, observed_at)
    values (new.id, new.price, coalesce(new.first_seen_at, now()));
  end if;
  return new;
end;
$$;

--
-- Name: record_owned_bike_values(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_owned_bike_values(p_at timestamp with time zone DEFAULT now()) RETURNS TABLE(user_id uuid, bike_id uuid, brand text, model text, year integer, value numeric, mileage integer, previous_value numeric, previous_month date)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_day   date := (p_at at time zone 'Europe/Lisbon')::date;
  v_month date := date_trunc('month', v_day)::date;
begin
  return query
  with due as (
    select b.id, b.user_id, b.motorcycle_id, b.year::integer as year,
           public.owned_bike_mileage(b.mileage_at_purchase, b.bought_on,
                                     coalesce(s.km_per_year, 5000), v_day) as km
    from public.owned_bikes b
    join auth.users u on u.id = b.user_id and not coalesce(u.is_anonymous, false)
    left join public.ownership_settings s on s.user_id = b.user_id
    where b.bought_on <= v_day
      and not exists (select 1 from public.owned_bike_values v
                      where v.bike_id = b.id and v.month = v_month)
  ),
  valued as (
    select d.id, d.km, bv.fair_price, bv.comparable_count
    from due d
    cross join lateral public.bike_value(d.motorcycle_id, d.year, d.km) bv
    where bv.comparable_count >= public.owned_bike_value_min_comparables()
      and bv.fair_price > 0
  ),
  kept as (
    insert into public.owned_bike_values as v
      (bike_id, month, value, mileage, comparables, recorded_at)
    select x.id, v_month, x.fair_price, x.km, x.comparable_count, p_at
    from valued x
    on conflict on constraint owned_bike_values_pkey do nothing
    returning v.bike_id, v.value, v.mileage
  )
  select b.user_id, k.bike_id, m.brand::text, m.model::text, b.year::integer,
         k.value, k.mileage, p.value, p.month
  from kept k
  join public.owned_bikes b on b.id = k.bike_id
  join public.motorcycles m on m.id = b.motorcycle_id
  left join lateral (
    select e.value, e.month from public.owned_bike_values e
    where e.bike_id = k.bike_id and e.month < v_month
    order by e.month desc limit 1
  ) p on true
  order by b.user_id, k.bike_id;
end;
$$;

--
-- Name: redeem_invite(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.redeem_invite(p_code text, p_email text, p_password text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_email  text := lower(btrim(p_email));
  v_status integer;
  v_body   jsonb;
  v_user   uuid;
begin
  perform 1 from public.invites i
  where i.code = p_code and i.used_at is null and i.expires_at > now()
  for update;
  if not found then
    raise exception 'This invite cannot be used' using errcode = 'P0002';
  end if;
  if v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then
    raise exception 'Invalid email' using errcode = '22023';
  end if;
  if char_length(coalesce(p_password, '')) < 8 then
    raise exception 'The password needs at least 8 characters' using errcode = '22023';
  end if;

  select r.status, r.body into v_status, v_body
  from public.auth_admin_request('POST', '/admin/users', jsonb_build_object(
    'email', v_email, 'password', p_password, 'email_confirm', true)) r;

  if v_status = 422
     and coalesce(v_body ->> 'error_code', v_body ->> 'code') = 'email_exists' then
    raise exception 'This email already has an account' using errcode = '23505';
  elsif v_status = 422
     and coalesce(v_body ->> 'error_code', v_body ->> 'code') = 'weak_password' then
    raise exception 'The password is too weak' using errcode = '22023';
  elsif v_status not between 200 and 299 or v_body ->> 'id' is null then
    raise exception 'Supabase Auth answered % %', v_status,
      coalesce(v_body ->> 'msg', v_body ->> 'message', '')
      using errcode = '58000';
  end if;

  v_user := (v_body ->> 'id')::uuid;
  update public.invites
  set used_at = now(), used_by = v_user
  where code = p_code;
  return v_user;
end;
$_$;

--
-- Name: refresh_collected_model(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_collected_model(p_motorcycle_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_was boolean;
  v_now boolean;
  v_min integer;
  v_followed boolean;
  v_follow_min integer;
  v_request_min integer;
begin
  select m.is_active into v_was
  from public.motorcycles m where m.id = p_motorcycle_id
  for update;

  select count(*) > 0, min(u.min_year) into v_followed, v_follow_min
  from public.user_models u
  where u.motorcycle_id = p_motorcycle_id and u.tracked;

  -- min() is null without requests (greatest() would turn it into 1990).
  select min(greatest(r.year - 3, 1990)) into v_request_min
  from public.bike_value_requests r
  where r.motorcycle_id = p_motorcycle_id
    and r.requested_at > now()
        - pg_catalog.make_interval(days => public.bike_value_request_days());

  v_now := v_followed or v_request_min is not null;
  -- least() ignores nulls: whichever of the two is known.
  v_min := least(v_follow_min, v_request_min);

  update public.motorcycles
  set is_active = v_now,
      min_year = coalesce(v_min, min_year),
      collected_since = case
        when not v_now then null
        when v_was then collected_since
        else now()
      end,
      updated_at = now()
  where id = p_motorcycle_id;

  if v_now and not v_was then
    update public.listings l
    set motorcycle_id = m.id
    from public.motorcycles m
    where m.id = p_motorcycle_id
      and l.motorcycle_id is null
      and lower(l.brand) = lower(m.brand)
      and lower(l.model) = lower(m.model);
  elsif v_was and not v_now then
    update public.listings set motorcycle_id = null
    where motorcycle_id = p_motorcycle_id;
  end if;

  if v_now is distinct from v_was then
    perform public.recalculate_deal_scores();
  end if;
end;
$$;

--
-- Name: refresh_fuel_prices(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_fuel_prices() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_response extensions.http_response;
  v_count    integer;
begin
  begin
    perform extensions.http_set_curlopt('CURLOPT_TIMEOUT_MS', '20000');
    v_response := extensions.http((
      'GET',
      'https://precoscombustiveis.dgeg.gov.pt/api/PrecoComb/PMD'
        || '?idsTiposComb=3201'
        || '&dataIni=' || to_char(current_date - 7, 'YYYY-MM-DD')
        || '&dataFim=' || to_char(current_date, 'YYYY-MM-DD')
        || '&qtdPorPagina=10&pagina=1&orderDesc=1',
      array[extensions.http_header('Accept', 'application/json'),
            extensions.http_header('User-Agent',
              'MotorcycleDealTracker/0.1 (personal project, low volume)')],
      null,
      null
    )::extensions.http_request);
  exception when others then
    raise warning 'Fuel prices not read: %', sqlerrm;
    return null;
  end;

  if v_response.status <> 200 then
    raise warning 'Fuel prices not read: HTTP %', v_response.status;
    return null;
  end if;

  begin
    insert into public.fuel_prices (fuel, day, price, stations)
    select 'petrol_95', r.day, r.price, r.stations
    from (
      select (e ->> 'Data')::date as day,
             public.fuel_price_from_text(e ->> 'PrecoMedio') as price,
             case when e ->> 'NumPostos' ~ '^[0-9]+$'
                  then (e ->> 'NumPostos')::integer end as stations
      from jsonb_array_elements(
             case when jsonb_typeof(v_response.content::jsonb -> 'resultado') = 'array'
                  then v_response.content::jsonb -> 'resultado'
                  else '[]'::jsonb end) e
    ) r
    where r.day is not null and r.price > 0 and r.price < 10
    on conflict (fuel, day) do update
      set price = excluded.price,
          stations = excluded.stations,
          fetched_at = now();
    get diagnostics v_count = row_count;
  exception when others then
    raise warning 'Fuel prices not understood: %', sqlerrm;
    return null;
  end;

  delete from public.fuel_prices where day < current_date - 400;
  return v_count;
end;
$_$;

--
-- Name: refresh_new_prices_from_ads(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_new_prices_from_ads() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  n integer;
begin
  with ads as (
    select l.motorcycle_id,
           count(*)::smallint as ad_count,
           round(percentile_cont(0.5) within group (order by l.price)::numeric)
             as median_price
    from public.listings l
    where l.status in ('active', 'price_changed')
      and l.duplicate_of is null
      and l.motorcycle_id is not null
      and public.new_bike_ad(l.year, l.mileage, l.price, l.seller_type,
            coalesce(l.text_signals,
                     public.description_signals(l.variant, l.description)))
    group by l.motorcycle_id
    having count(*) >= 3
  ),
  wanted as (
    select m.id, a.median_price, a.ad_count
    from public.motorcycles m
    left join ads a on a.motorcycle_id = m.id
  )
  update public.motorcycles m
  set new_price_from_ads = w.median_price,
      new_price_ad_count = w.ad_count
  from wanted w
  where m.id = w.id
    and (m.new_price_from_ads is distinct from w.median_price
         or m.new_price_ad_count is distinct from w.ad_count);

  get diagnostics n = row_count;
  return n;
end;
$$;

--
-- Name: refresh_photo_hints(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_photo_hints(p_listings uuid[]) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  update public.listings l
  set photo_hints = public.photo_hint_codes(coalesce((
    select jsonb_agg(jsonb_build_object(
      'photo', f.photo,
      'scores', f.scores || coalesce(jsonb_build_object('learned', round(
        public.photo_learned_share(f.model, f.features)::numeric, 3)), '{}')))
    from public.listing_photo_features f
    where f.listing_id = l.id
  ), '[]'))
  where l.id = any (p_listings)
$$;

--
-- Name: refresh_stock_photos(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_stock_photos(p_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  n integer;
begin
  with per_photo as (
    select h.listing_id,
           count(distinct o.listing_id) as others,
           count(distinct (ol.year, ol.mileage / 1000))
             filter (where (ol.year, ol.mileage / 1000)
                           is distinct from (l.year, l.mileage / 1000)) as other_bikes
    from public.listing_photo_hashes h
    join public.listings l on l.id = h.listing_id
    left join public.listing_photo_hashes o
      on o.bands && h.bands
     and o.listing_id <> h.listing_id
     and bit_count((o.hash # h.hash)::bit(64)) <= 5
    left join public.listings ol on ol.id = o.listing_id
    where h.listing_id = any(p_ids)
    group by h.listing_id, h.position
  ),
  per_listing as (
    select listing_id, bool_and(others >= 5 and other_bikes >= 3) as stock
    from per_photo
    group by listing_id
  )
  update public.listings l
  set stock_photos = coalesce(p.stock, false)
  from (select unnest(p_ids) as id) ids
  left join per_listing p on p.listing_id = ids.id
  where l.id = ids.id
    and l.stock_photos is distinct from coalesce(p.stock, false);
  get diagnostics n = row_count;
  return n;
end;
$$;

--
-- Name: refresh_vehicle_recalls(interval, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_vehicle_recalls(p_budget interval DEFAULT '00:02:00'::interval, p_pause double precision DEFAULT 3) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_started  timestamptz := clock_timestamp();
  v_doc      xml;
  v_report   record;
  v_read     integer := 0;
  v_found    integer;
  v_requests integer := 0;
begin
  if (select list_read_at is null or list_read_at < now() - interval '20 hours'
      from public.safety_gate_state where id) then
    v_doc := public.safety_gate_get(
      'https://ec.europa.eu/safety-gate-alerts/api/download/weeklyReport/list/xml/en');
    v_requests := 1;
    if v_doc is not null then
      begin
        insert into public.safety_gate_reports (reference, url, published_on)
        select r.reference, r.url, to_date(r.published, 'DD/MM/YYYY')
        from xmltable('/Safety-Gate/weeklyReport' passing v_doc
               columns reference text path 'reference',
                       published text path 'publicationDate',
                       url       text path 'URL') r
        where r.reference is not null
          and r.url like 'https://ec.europa.eu/safety-gate-alerts/api/download/weeklyReport/detail/xml/%'
          and r.published ~ '^\d{2}/\d{2}/\d{4}$'
          and to_date(r.published, 'DD/MM/YYYY') >= date '2010-01-01'
        on conflict (reference) do nothing;
        update public.safety_gate_state set list_read_at = now() where id;
      exception when others then
        raise warning 'Safety Gate list not understood: %', sqlerrm;
      end;
    end if;
  end if;

  for v_report in
    select reference, url from public.safety_gate_reports
    where read_at is null
    order by published_on desc, reference desc
  loop
    exit when clock_timestamp() - v_started > p_budget;
    if v_requests > 0 then perform pg_sleep(p_pause); end if;
    v_requests := v_requests + 1;
    v_doc := public.safety_gate_get(v_report.url);
    exit when v_doc is null;

    begin
      insert into public.vehicle_recalls (
        case_number, report, published_on, brand, product, name, model_type,
        production_dates, from_year, to_year, recall_code, alert_url,
        danger_en, country_en, match_keys)
      select n.case_number, v_report.reference,
             coalesce(to_date(n.published, 'DD-MM-YYYY'), current_date),
             n.brand, n.product, n.name, n.model_type, n.production_dates,
             y.from_year, y.to_year, n.recall_code,
             case when n.alert_url like 'https://ec.europa.eu/%' then n.alert_url end,
             n.danger, n.country,
             public.recall_match_keys(concat_ws(' ', n.product, n.name))
      from xmltable('/Safety-Gate/notifications' passing v_doc
             columns case_number      text path 'caseNumber',
                     published        text path 'publicationDate',
                     category         text path 'category',
                     product_raw      text path 'product',
                     brand_raw        text path 'brand',
                     name_raw         text path 'name',
                     model_type_raw   text path 'type_numberOfModel',
                     production_raw   text path 'productionDates',
                     recall_code_raw  text path 'companyRecallCode',
                     alert_url_raw    text path 'reference',
                     danger_raw       text path 'danger',
                     country_raw      text path 'notifyingCountry') x
      cross join lateral (
        select x.case_number, x.published,
               public.safety_gate_text(x.product_raw) as product,
               public.safety_gate_text(x.brand_raw) as brand,
               public.safety_gate_text(x.name_raw) as name,
               public.safety_gate_text(x.model_type_raw) as model_type,
               public.safety_gate_text(x.production_raw) as production_dates,
               public.safety_gate_text(x.recall_code_raw) as recall_code,
               public.safety_gate_text(x.alert_url_raw) as alert_url,
               public.safety_gate_text(x.danger_raw) as danger,
               public.safety_gate_text(x.country_raw) as country
      ) n
      cross join lateral public.recall_years(n.production_dates) y
      where x.case_number is not null
        and x.category = 'Motor vehicles'
        and x.product_raw ~* 'motor ?cycle|motorbike|moped|scooter'
        and (x.published is null or x.published ~ '^\d{2}-\d{2}-\d{4}$')
      on conflict (case_number) do nothing;
      get diagnostics v_found = row_count;
    exception when others then
      raise warning 'Safety Gate report % not understood: %', v_report.reference, sqlerrm;
      exit;
    end;

    -- The same report in Portuguese (Safety Gate's translation), only
    -- for reports with motorcycle recalls; without it the English stays.
    if v_found > 0 then
      perform pg_sleep(p_pause);
      v_requests := v_requests + 1;
      v_doc := public.safety_gate_get(replace(v_report.url, 'language=en', 'language=pt'));
      if v_doc is not null then
        begin
          update public.vehicle_recalls r
          set danger_pt = public.safety_gate_text(x.danger),
              country_pt = public.safety_gate_text(x.country)
          from xmltable('/Safety-Gate/notifications' passing v_doc
                 columns case_number text path 'caseNumber',
                         danger      text path 'danger',
                         country     text path 'notifyingCountry') x
          where r.case_number = x.case_number
            and r.report = v_report.reference;
        exception when others then
          raise warning 'Safety Gate report % (pt) not understood: %', v_report.reference, sqlerrm;
        end;
      end if;
    end if;

    update public.safety_gate_reports
    set read_at = now(), recalls = v_found
    where reference = v_report.reference;
    v_read := v_read + 1;
  end loop;

  return v_read;
end;
$_$;

--
-- Name: rematch_listings(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rematch_listings(p_source text, p_matches jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  n integer;
begin
  update public.listings l
  set motorcycle_id = nullif(m.value ->> 'motorcycle_id', '')::uuid,
      brand         = m.value ->> 'brand',
      model         = m.value ->> 'model'
  from jsonb_each(p_matches) m
  where l.source = p_source
    and l.source_listing_id = m.key
    and l.motorcycle_id is distinct from
        nullif(m.value ->> 'motorcycle_id', '')::uuid;

  get diagnostics n = row_count;
  return n;
end;
$$;

--
-- Name: remove_account(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remove_account(p_user uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_status  integer;
  v_models  uuid[];
  v_model   uuid;
begin
  perform public.require_admin();
  if p_user = auth.uid() then
    raise exception 'You cannot remove your own account' using errcode = '22023';
  end if;
  if not exists (select 1 from auth.users u
                 where u.id = p_user and not coalesce(u.is_anonymous, false)) then
    raise exception 'Unknown account %', p_user using errcode = 'P0002';
  end if;

  select coalesce(array_agg(m.motorcycle_id), '{}') into v_models
  from public.user_models m where m.user_id = p_user and m.tracked;

  select r.status into v_status
  from public.auth_admin_request('DELETE', '/admin/users/' || p_user) r;
  if v_status not between 200 and 299 and v_status <> 404 then
    raise exception 'Supabase Auth answered %', v_status using errcode = '58000';
  end if;

  -- Auth deletes the user in its own transaction; drop what is ours now
  -- too, so the collection follows at once.
  delete from public.user_models where user_id = p_user;
  foreach v_model in array v_models loop
    perform public.refresh_collected_model(v_model);
  end loop;
end;
$$;

--
-- Name: request_ad_check(text, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_ad_check(p_url text, p_motorcycle_id uuid, p_year integer, p_mileage integer DEFAULT NULL::integer) RETURNS TABLE(request_id uuid, listing_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_url text := btrim(p_url);
  v_listing uuid;
  v_id uuid;
begin
  perform public.require_account();

  if public.ad_link_source(v_url) is null then
    raise exception 'Not an OLX or Standvirtual ad link' using errcode = '22023';
  end if;
  -- Kept without the query and fragment (tracking, the site's own state).
  v_url := regexp_replace(v_url, '[?#].*$', '');
  if not exists (select 1 from public.motorcycles m where m.id = p_motorcycle_id) then
    raise exception 'Unknown model %', p_motorcycle_id using errcode = 'P0002';
  end if;
  if p_year < 1990 or p_year > extract(year from now())::integer + 1 then
    raise exception 'Year % is out of range', p_year using errcode = '22023';
  end if;
  if p_mileage < 0 then
    raise exception 'Mileage % is invalid', p_mileage using errcode = '22023';
  end if;

  select l.id into v_listing
  from public.listings l
  where l.id = public.listing_for_ad(v_url)
    and l.scored_at is not null;

  if v_listing is null then
    select r.id into v_id
    from public.bike_value_requests r
    where r.user_id = auth.uid()
      and public.ad_link_source(r.ad_url) = public.ad_link_source(v_url)
      and public.ad_link_code(r.ad_url) = public.ad_link_code(v_url)
      and r.answered_at is null
    limit 1;
    if v_id is not null then
      return query select v_id, null::uuid;
      return;
    end if;

    if (select count(*) from public.bike_value_requests r
        where r.user_id = auth.uid() and r.waited
          and r.requested_at > now() - interval '1 day') >= 3 then
      raise exception 'At most 3 requests that wait for a collection a day'
        using errcode = '54000';
    end if;
  end if;

  insert into public.bike_value_requests
    (motorcycle_id, year, mileage, waited, answered_at, ad_url)
  values
    (p_motorcycle_id, p_year, p_mileage, v_listing is null,
     case when v_listing is not null then now() end, v_url)
  returning id into v_id;

  perform public.refresh_collected_model(p_motorcycle_id);

  return query select v_id, v_listing;
end;
$_$;

--
-- Name: request_bike_value(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_bike_value(p_motorcycle_id uuid, p_year integer, p_mileage integer DEFAULT NULL::integer) RETURNS TABLE(request_id uuid, ready boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_ready boolean;
  v_id uuid;
begin
  perform public.require_account();

  if not exists (select 1 from public.motorcycles m where m.id = p_motorcycle_id) then
    raise exception 'Unknown model %', p_motorcycle_id using errcode = 'P0002';
  end if;
  if p_year < 1990 or p_year > extract(year from now())::integer + 1 then
    raise exception 'Year % is out of range', p_year using errcode = '22023';
  end if;
  if p_mileage < 0 then
    raise exception 'Mileage % is invalid', p_mileage using errcode = '22023';
  end if;

  v_ready := public.bike_value_ready(p_motorcycle_id, p_year);

  if not v_ready then
    select r.id into v_id
    from public.bike_value_requests r
    where r.user_id = auth.uid()
      and r.motorcycle_id = p_motorcycle_id
      and r.year = p_year
      and r.mileage is not distinct from p_mileage
      and r.answered_at is null
    limit 1;
    if v_id is not null then
      return query select v_id, false;
      return;
    end if;

    if (select count(*) from public.bike_value_requests r
        where r.user_id = auth.uid() and r.waited
          and r.requested_at > now() - interval '1 day') >= 3 then
      raise exception 'At most 3 valuations that wait for a collection a day'
        using errcode = '54000';
    end if;
  end if;

  insert into public.bike_value_requests
    (motorcycle_id, year, mileage, waited, answered_at)
  values
    (p_motorcycle_id, p_year, p_mileage, not v_ready,
     case when v_ready then now() end)
  returning id into v_id;

  -- A ready request also keeps the model collected (its figures stay
  -- fresh for the next 30 days' requests).
  perform public.refresh_collected_model(p_motorcycle_id);

  return query select v_id, v_ready;
end;
$$;

--
-- Name: request_photo_exam(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_photo_exam(p_listing uuid) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_listing public.listings%rowtype;
begin
  perform public.require_account();

  select l.* into v_listing
  from public.listings l
  join public.motorcycles m on m.id = l.motorcycle_id and m.is_active
  where l.id = p_listing
    and l.status in ('active', 'price_changed');
  if not found then
    raise exception 'Listing % is not collected or not live', p_listing
      using errcode = 'P0002';
  end if;
  if v_listing.photos_examined_all_at is not null then
    return null;
  end if;
  if cardinality(v_listing.images) <= 3 then
    raise exception 'Listing % has no photos beyond the first 3', p_listing
      using errcode = '22023';
  end if;

  if v_listing.photo_exam_requested_at is not null then
    -- Already waiting: this account is told too when it is done.
    insert into public.photo_exam_requests (user_id, listing_id)
    values (auth.uid(), p_listing)
    on conflict (user_id, listing_id) do nothing;
    return v_listing.photo_exam_requested_at;
  end if;

  if (select count(*) from public.photo_exam_requests r
      where r.user_id = auth.uid()
        and r.requested_at > now() - interval '1 day') >= 5 then
    raise exception 'At most 5 photo examinations a day'
      using errcode = '54000';
  end if;

  insert into public.photo_exam_requests (user_id, listing_id)
  values (auth.uid(), p_listing)
  on conflict (user_id, listing_id) do update set requested_at = now();

  update public.listings
  set photo_exam_requested_at = now()
  where id = p_listing;

  perform public.dispatch_workflow('photos.yml');

  return now();
end;
$$;

--
-- Name: require_account(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.require_account() RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
begin
  if auth.uid() is null
     or coalesce((auth.jwt() ->> 'is_anonymous')::boolean, true) then
    raise exception 'Sign in to change the tracked models'
      using errcode = '42501';
  end if;
end;
$$;

--
-- Name: require_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.require_admin() RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not public.is_admin() then
    raise exception 'Only an admin can do this' using errcode = '42501';
  end if;
end;
$$;

--
-- Name: risk_assessment(numeric, numeric, integer, integer, text, text, boolean, boolean, integer, boolean, text, date, integer, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.risk_assessment(p_price numeric, p_market_price numeric, p_year integer, p_mileage integer, p_description text, p_location text, p_details_known boolean DEFAULT false, p_private_seller boolean DEFAULT false, p_registrations integer DEFAULT NULL::integer, p_service_book boolean DEFAULT NULL::boolean, p_origin text DEFAULT NULL::text, p_warranty_until date DEFAULT NULL::date, p_relists integer DEFAULT 0, p_on_sale_since timestamp with time zone DEFAULT NULL::timestamp with time zone, p_variant text DEFAULT NULL::text) RETURNS TABLE(risk_score smallint, reasons text[])
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select * from public.risk_from_signals(
    p_price, p_market_price, p_year, p_mileage, p_description, p_location,
    p_details_known, p_private_seller, p_registrations, p_service_book,
    p_origin, p_warranty_until, p_relists, p_on_sale_since,
    public.description_signals(p_variant, p_description))
$$;

--
-- Name: risk_from_signals(numeric, numeric, integer, integer, text, text, boolean, boolean, integer, boolean, text, date, integer, timestamp with time zone, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.risk_from_signals(p_price numeric, p_market_price numeric, p_year integer, p_mileage integer, p_description text, p_location text, p_details_known boolean, p_private_seller boolean, p_registrations integer, p_service_book boolean, p_origin text, p_warranty_until date, p_relists integer, p_on_sale_since timestamp with time zone, p_text_signals text[]) RETURNS TABLE(risk_score smallint, reasons text[])
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  -- Measured against the value of the bike with its damage
  -- (damage_allowance): a damaged bike priced like one isn't suspicious.
  with pct as (
    select case
      when p_price is null or p_market_price is null or p_market_price <= 0
        then null
      else (m.value - p_price) / m.value * 100
    end as below
    from (select p_market_price
                 * (1 - public.damage_allowance(p_text_signals)) as value) m
  ),
  signals(code, points) as (
    select 'price_far_below_market'::text, 45 from pct where below >= 25
    union all
    select 'price_below_market', 25 from pct where below >= 15 and below < 25
    union all
    select 'possible_accident', 30
    where 'possible_accident' = any(p_text_signals)
    union all
    select 'needs_repair', 20
    where 'needs_repair' = any(p_text_signals)
    union all
    select 'cosmetic_damage', 5
    where 'cosmetic_damage' = any(p_text_signals)
    union all
    select 'photos_reused', 10
    where 'photos_reused' = any(p_text_signals)
    union all
    select 'stock_photos', 10
    where 'stock_photos' = any(p_text_signals)
    union all
    select 'no_mileage', 15 where p_mileage is null
    union all
    select 'no_year', 10 where p_year is null
    union all
    -- A placeholder ("0", "1", "10") on a bike three or more years old, or
    -- far more than anyone rides in a year (bikes average 3-6 000 km). The
    -- age counts from mid-year registration in days, at least one year, as
    -- expected_mileage does.
    select 'suspicious_mileage', 10
    where p_mileage is not null and p_year is not null
      and (
        (p_mileage < 100
          and p_year <= extract(year from current_date)::integer - 3)
        or p_mileage::numeric
           / greatest(1, public.decimal_year() - (p_year + 0.5))
           > 25000
      )
    union all
    -- Only meaningful once the page was read, and only for private sellers:
    -- dealers rarely write more than boilerplate.
    select 'thin_description', 10
    where p_details_known and p_private_seller
      and char_length(btrim(coalesce(p_description, ''))) < 40
    union all
    select 'no_location', 5
    where nullif(btrim(coalesce(p_location, '')), '') is null
    union all
    select 'many_owners', 15 where p_registrations >= 3
    union all
    select 'no_service_book', 10 where p_service_book = false
    union all
    -- Not yet legalised in Portugal (legalisation_status): more than
    -- imported, which it replaces.
    select v, case v when 'not_legalised_outside_eu' then 20 else 15 end
    from unnest(p_text_signals) v
    where v in ('not_legalised', 'not_legalised_outside_eu')
    union all
    select 'imported', 10 where p_origin is not null and p_origin <> 'national'
      and not coalesce(p_text_signals && array['not_legalised', 'not_legalised_outside_eu'], false)
    union all
    -- The text says something else than the ad's own fields.
    select c, 10 from unnest(public.text_contradictions(
      p_description, p_year, p_mileage, p_origin, p_service_book)) c
    union all
    -- A bike put up again after its ad went (mark_relists): it did not sell
    -- at that price. More when it happened twice or the bike has been on
    -- sale for over 90 days counting the earlier ads.
    select 'relisted_often', 10
    where p_relists >= 2
       or (p_relists = 1 and p_on_sale_since < now() - interval '90 days')
    union all
    select 'relisted', 5
    where p_relists = 1
      and (p_on_sale_since is null or p_on_sale_since >= now() - interval '90 days')
    union all
    -- An A2 (35 kW) version, still held back or unlocked (power_version).
    select v, case v when 'a2_limited' then 15 else 10 end
    from unnest(p_text_signals) v
    where v in ('a2_limited', 'a2_unlocked')
    union all
    -- The seller edited the ad after it was found, in their own favour
    -- (N.62: listings_track_facts): fewer km, or a newer year.
    select 'mileage_lowered', 15
    where 'mileage_lowered' = any(p_text_signals)
    union all
    select 'year_raised', 10
    where 'year_raised' = any(p_text_signals)
    union all
    -- The ad's field, or the text when the field is empty.
    select 'first_owner', -5
    where p_registrations = 1
       or (p_registrations is null
           and 'single_owner_in_text' = any(p_text_signals))
    union all
    select 'service_book', -5 where p_service_book
    union all
    select 'under_warranty', -10 where p_warranty_until >= current_date
  )
  select
    greatest(0, least(100, coalesce(sum(points), 0)))::smallint,
    coalesce(array_agg(code order by points desc, code), '{}'::text[])
  from signals
$$;

--
-- Name: safety_gate_get(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.safety_gate_get(p_url text) RETURNS xml
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_response extensions.http_response;
begin
  perform extensions.http_set_curlopt('CURLOPT_TIMEOUT_MS', '30000');
  v_response := extensions.http((
    'GET',
    p_url,
    array[extensions.http_header('Accept', 'application/xml'),
          extensions.http_header('User-Agent',
            'MotorcycleDealTracker/0.1 (personal project, low volume)')],
    null,
    null
  )::extensions.http_request);
  if v_response.status <> 200 then
    raise warning 'Safety Gate not read (%): HTTP %', p_url, v_response.status;
    return null;
  end if;
  return xmlparse(document v_response.content);
exception when others then
  raise warning 'Safety Gate not read (%): %', p_url, sqlerrm;
  return null;
end;
$$;

--
-- Name: safety_gate_text(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.safety_gate_text(p_text text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select nullif(btrim(regexp_replace(coalesce(p_text, ''), '^\s*null\s+', ''), E' \t\r\n'), '')
$$;

--
-- Name: save_push_subscription(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_push_subscription(p_endpoint text, p_p256dh text, p_auth text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  android boolean := p_endpoint ~ '^fcm:[A-Za-z0-9_:.-]{20,}$';
begin
  perform public.require_account();

  if not android
     and (not public.push_endpoint_allowed(p_endpoint)
          or nullif(btrim(p_p256dh), '') is null
          or nullif(btrim(p_auth), '') is null) then
    raise exception 'Invalid push subscription' using errcode = '22023';
  end if;

  insert into public.push_subscriptions (endpoint, user_id, p256dh, auth)
  values (p_endpoint, auth.uid(),
          case when android then '' else btrim(p_p256dh) end,
          case when android then '' else btrim(p_auth) end)
  on conflict (endpoint) do update
  set user_id = excluded.user_id,
      p256dh = excluded.p256dh,
      auth = excluded.auth,
      created_at = now();
end;
$_$;

--
-- Name: saved_search_single_model(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.saved_search_single_model() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'UPDATE' or new.motorcycle_id is not null then
    new.motorcycle_ids := case
      when new.motorcycle_id is null then '{}'::uuid[]
      else array[new.motorcycle_id]
    end;
    new.motorcycle_id := null;
  end if;
  return new;
end;
$$;

--
-- Name: score_check_bands(integer, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.score_check_bands(p_days integer DEFAULT 60, p_horizon integer DEFAULT 14, p_since timestamp with time zone DEFAULT '2026-11-12 13:10:00+00'::timestamp with time zone) RETURNS TABLE(band text, ads integer, sold_within integer, share numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with ads as (
    select case
             when l.last_deal_score >= 80 then '80-100'
             when l.last_deal_score >= 60 then '60-79'
             when l.last_deal_score >= 40 then '40-59'
             else '0-39'
           end as band,
           public.exit_kind(l) in ('sold_in_text', 'likely_sold')
             and l.last_seen_at - l.first_seen_at
                 <= make_interval(days => p_horizon) as sold
    from public.listings l
    where l.first_seen_at >= now() - make_interval(days => p_days)
      and l.first_seen_at <= now() - make_interval(days => p_horizon)
      and l.first_seen_at >= p_since
      and (l.published_at is null
           or l.published_at >= l.first_seen_at - interval '2 days')
      and l.duplicate_of is null
      and l.motorcycle_id is not null
      and l.price >= 300
      and l.last_deal_score is not null
  )
  select a.band,
         count(*)::integer,
         count(*) filter (where a.sold)::integer,
         round(100.0 * count(*) filter (where a.sold) / count(*), 1)
  from ads a
  group by a.band
  order by a.band desc;
$$;

--
-- Name: score_check_models(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.score_check_models(p_days integer DEFAULT 28) RETURNS TABLE(model text, gone integer, sold_in_text integer, likely_sold integer, relisted integer, still_listed integer, expired integer, seen_once integer, sold_with_position integer, sold_position numeric, live_with_position integer, live_position numeric, sold_dropped integer, sold_drop_pct numeric, sold_days numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with gone as (
    select l.motorcycle_id,
           public.exit_kind(l) as kind,
           case when not coalesce(l.text_signals,
                                  public.description_signals(l.variant, l.description))
                     && array['possible_accident', 'needs_repair',
                              'not_legalised', 'not_legalised_outside_eu']
                then l.last_pct_below_market end as position,
           100 * (1 - l.price / nullif(greatest(l.initial_price, l.price_before_drop, l.price), 0))
             as drop_pct,
           extract(epoch from l.last_seen_at
                   - coalesce(l.published_at, l.first_seen_at)) / 86400 as days
    from public.listings l
    where l.status in ('removed', 'sold')
      and l.last_seen_at >= now() - make_interval(days => p_days)
      and l.duplicate_of is null
      and l.motorcycle_id is not null
      and l.price >= 300
  ),
  live as (
    select l.motorcycle_id, public.market_position(l) as position
    from public.listings l
    where l.status in ('active', 'price_changed')
      and l.duplicate_of is null
      and l.motorcycle_id is not null
  ),
  per_gone as (
    select g.motorcycle_id,
           count(*)::integer as gone,
           count(*) filter (where g.kind = 'sold_in_text')::integer as sold_in_text,
           count(*) filter (where g.kind = 'likely_sold')::integer as likely_sold,
           count(*) filter (where g.kind = 'relisted')::integer as relisted,
           count(*) filter (where g.kind = 'still_listed')::integer as still_listed,
           count(*) filter (where g.kind = 'expired')::integer as expired,
           count(*) filter (where g.kind = 'seen_once')::integer as seen_once,
           count(g.position) filter (where g.kind in ('sold_in_text', 'likely_sold'))::integer
             as sold_with_position,
           round((percentile_cont(0.5) within group (order by g.position)
                  filter (where g.kind in ('sold_in_text', 'likely_sold')))::numeric, 1)
             as sold_position,
           count(*) filter (where g.kind in ('sold_in_text', 'likely_sold')
                              and g.drop_pct >= 1)::integer as sold_dropped,
           round((percentile_cont(0.5) within group (order by g.drop_pct)
                  filter (where g.kind in ('sold_in_text', 'likely_sold')
                            and g.drop_pct >= 1))::numeric, 1)
             as sold_drop_pct,
           round((percentile_cont(0.5) within group (order by g.days)
                  filter (where g.kind in ('sold_in_text', 'likely_sold')))::numeric, 0)
             as sold_days
    from gone g
    group by g.motorcycle_id
  ),
  per_live as (
    select v.motorcycle_id,
           count(v.position)::integer as live_with_position,
           round((percentile_cont(0.5) within group (order by v.position))::numeric, 1)
             as live_position
    from live v
    group by v.motorcycle_id
  )
  select m.brand || ' ' || m.model,
         g.gone, g.sold_in_text, g.likely_sold, g.relisted, g.still_listed,
         g.expired, g.seen_once, g.sold_with_position, g.sold_position,
         coalesce(v.live_with_position, 0), v.live_position,
         g.sold_dropped, g.sold_drop_pct, g.sold_days
  from per_gone g
  join public.motorcycles m on m.id = g.motorcycle_id
  left join per_live v on v.motorcycle_id = g.motorcycle_id
  order by g.gone desc, 1;
$$;

--
-- Name: send_telegram(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_telegram(p_text text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  token text;
  chat  text;
begin
  select s.decrypted_secret into token
  from vault.decrypted_secrets s where s.name = 'telegram_bot_token';
  select s.decrypted_secret into chat
  from vault.decrypted_secrets s where s.name = 'telegram_chat_id';

  if token is null or chat is null then
    raise warning 'telegram_bot_token or telegram_chat_id is not in the Vault; message not sent';
    return null;
  end if;

  return net.http_post(
    url := 'https://api.telegram.org/bot' || token || '/sendMessage',
    body := jsonb_build_object('chat_id', chat, 'text', p_text),
    headers := jsonb_build_object('Content-Type', 'application/json'),
    timeout_milliseconds := 10000
  );
end;
$$;

--
-- Name: set_admin(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_admin(p_user uuid, p_admin boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform public.require_admin();
  if p_user = auth.uid() then
    raise exception 'You cannot change your own admin access' using errcode = '22023';
  end if;
  if not exists (select 1 from auth.users u
                 where u.id = p_user and not coalesce(u.is_anonymous, false)) then
    raise exception 'Unknown account %', p_user using errcode = 'P0002';
  end if;
  if p_admin then
    insert into public.app_admins (user_id) values (p_user) on conflict do nothing;
  else
    delete from public.app_admins where user_id = p_user;
  end if;
end;
$$;

--
-- Name: set_initial_price(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_initial_price() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  new.initial_price := coalesce(new.initial_price, new.price);
  return new;
end;
$$;

--
-- Name: set_model_colours(uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_model_colours(p_motorcycle_id uuid, p_colours text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform public.require_account();

  if not exists (select 1 from public.motorcycles m where m.id = p_motorcycle_id) then
    raise exception 'Unknown model %', p_motorcycle_id using errcode = 'P0002';
  end if;

  insert into public.user_models (user_id, motorcycle_id, tracked, min_year, colours)
  select auth.uid(), m.id, false, m.min_year, coalesce(p_colours, '{}')
  from public.motorcycles m where m.id = p_motorcycle_id
  on conflict (user_id, motorcycle_id)
  do update set colours = excluded.colours, updated_at = now();
end;
$$;

--
-- Name: set_model_min_year(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_model_min_year(p_motorcycle_id uuid, p_min_year integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform public.require_account();

  if p_min_year < 1990 or p_min_year > extract(year from now())::integer + 1 then
    raise exception 'Year % is out of range', p_min_year using errcode = '22023';
  end if;
  if not exists (select 1 from public.motorcycles m where m.id = p_motorcycle_id) then
    raise exception 'Unknown model %', p_motorcycle_id using errcode = 'P0002';
  end if;

  -- A year for a model not followed is kept for when it is.
  insert into public.user_models (user_id, motorcycle_id, tracked, min_year)
  values (auth.uid(), p_motorcycle_id, false, p_min_year)
  on conflict (user_id, motorcycle_id)
  do update set min_year = excluded.min_year, updated_at = now();

  perform public.refresh_collected_model(p_motorcycle_id);
end;
$$;

--
-- Name: set_model_new_price(uuid, numeric, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_model_new_price(p_motorcycle_id uuid, p_price numeric, p_checked_at date DEFAULT CURRENT_DATE) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform public.require_admin();

  if p_price is not null and (p_price <= 0 or p_price > 200000) then
    raise exception 'Price % is out of range', p_price using errcode = '22023';
  end if;

  update public.motorcycles
  set new_price_reference  = p_price,
      new_price_checked_at = case when p_price is null then null
                                  else coalesce(p_checked_at, current_date) end,
      updated_at           = now()
  where id = p_motorcycle_id;

  if not found then
    raise exception 'Unknown model %', p_motorcycle_id using errcode = 'P0002';
  end if;
end;
$$;

--
-- Name: set_model_tracked(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_model_tracked(p_motorcycle_id uuid, p_tracked boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform public.require_account();

  if not exists (select 1 from public.motorcycles m where m.id = p_motorcycle_id) then
    raise exception 'Unknown model %', p_motorcycle_id using errcode = 'P0002';
  end if;

  insert into public.user_models (user_id, motorcycle_id, tracked, min_year)
  select auth.uid(), m.id, p_tracked, m.min_year
  from public.motorcycles m where m.id = p_motorcycle_id
  on conflict (user_id, motorcycle_id)
  do update set tracked = excluded.tracked, updated_at = now();

  perform public.refresh_collected_model(p_motorcycle_id);
end;
$$;

--
-- Name: set_photo_mark(uuid, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_photo_mark(p_listing uuid, p_photo integer, p_problem boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform public.require_admin();
  if p_photo is null or p_photo not between 0 and 2 then
    raise exception 'Only the first 3 photos can be marked' using errcode = '22023';
  end if;
  if p_problem is null then
    delete from public.photo_marks
    where user_id = auth.uid() and listing_id = p_listing and photo = p_photo;
  else
    insert into public.photo_marks (user_id, listing_id, photo, problem)
    values (auth.uid(), p_listing, p_photo, p_problem)
    on conflict (user_id, listing_id, photo)
      do update set problem = excluded.problem, marked_at = now();
  end if;
end;
$$;

--
-- Name: set_search_keys(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_search_keys(p_source text, p_keys jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  n integer;
begin
  update public.listings l
  set search_key = k.value
  from jsonb_each_text(p_keys) k
  where l.source = p_source
    and l.source_listing_id = k.key
    and l.search_key is distinct from k.value;

  get diagnostics n = row_count;
  return n;
end;
$$;

--
-- Name: share_favourites(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.share_favourites() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_code text := translate(encode(uuid_send(gen_random_uuid()), 'base64'), '+/=', '-_');
begin
  perform public.require_account();
  insert into public.favourite_shares (owner_id, code, code_expires_at)
  values (auth.uid(), v_code, now() + interval '14 days')
  on conflict (owner_id) do update
    set code = excluded.code, code_expires_at = excluded.code_expires_at;
  return v_code;
end;
$$;

--
-- Name: listing_favourites; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.listing_favourites (
    user_id uuid DEFAULT auth.uid() NOT NULL,
    listing_id uuid NOT NULL,
    note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    checklist jsonb DEFAULT '{}'::jsonb NOT NULL,
    target_price numeric(10,2),
    target_set_at timestamp with time zone,
    visit_at timestamp with time zone,
    visit_reminded_at timestamp with time zone,
    seen_at timestamp with time zone,
    seen_price numeric(10,2),
    seen_mileage integer,
    seen_status public.listing_status,
    CONSTRAINT listing_favourites_checklist_object CHECK (((jsonb_typeof(checklist) = 'object'::text) AND (octet_length((checklist)::text) <= 32000))),
    CONSTRAINT listing_favourites_note_check CHECK ((char_length(note) <= 2000)),
    CONSTRAINT listing_favourites_target_price_check CHECK ((target_price > (0)::numeric))
);

--
-- Name: COLUMN listing_favourites.checklist; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.listing_favourites.checklist IS 'Viewing checklist marks per item key: {"mark": "ok"|"issue", "note": text}.';

--
-- Name: COLUMN listing_favourites.seen_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.listing_favourites.seen_at IS 'When the owner last opened the ad (N.97); seen_price, seen_mileage and seen_status are the ad then.';

--
-- Name: shared_favourites(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.shared_favourites(p_owner uuid) RETURNS SETOF public.listing_favourites
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select f.*
  from public.listing_favourites f
  where f.user_id = p_owner
    and exists (
      select 1 from public.favourite_shares s
      where s.owner_id = p_owner and s.viewer_id = auth.uid()
    )
  order by f.created_at desc
$$;

--
-- Name: single_owner_in_text(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.single_owner_in_text(p_variant text, p_description text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select regexp_replace(
           lower(concat_ws(' ', p_variant, p_description)),
           '(\mn[ãa]o\M|\mnunca\M|\mnot\M)\s+([^\s.,!?;]+\s+){0,3}?'
           '(primeir[oa]|[úu]nic[oa]|1\s*[ºªoa]|dono|first|one|single|only)\S*',
           ' ', 'g'
         ) ~ ('(primeiro|[úu]nico|1\s*[ºo])\s+(e\s+[úu]nico\s+)?(dono|propriet[áa]rio)'
              '|\m(dono|propriet[áa]rio)\s+[úu]nico'
              '|\m(apenas|s[óo]|somente)\s+(um|1)\s+(dono|propriet[áa]rio)'
              '|\m(um|1)\s+s[óo]\s+(dono|propriet[áa]rio)'
              '|\m1\s+(dono|propriet[áa]rio)\M'
              '|(primeira|1\s*[ªa])\s+m[ãa]o'
              '|\m(first|one|single|only)\s+owner')
$$;

--
-- Name: sold_in_text(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sold_in_text(p_variant text, p_description text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  with t as (
    select lower(coalesce(p_variant, '')) as variant,
           lower(coalesce(p_description, '')) as description,
           -- The word on its own, not how the bike is sold.
           '\m(vendid|reservad)[oa]s?\M(?!\s*(com|sem|no|na|nos|nas|em|ao|aos|à|a|pelo|pela|por|para|c/|s/|apenas|só|so|tal|como|ja|já|nova|novo|nunca)(\s|$|[[:punct:]]))'
             as bare,
           -- "não está vendida", "ainda não foi reservada".
           '\mn[aã]o\s+((est[aá]|foi|ser[aá]|se\s+encontra)\s+)?(vendid|reservad)[oa]s?\M'
             as denied
  )
  select (t.variant ~ t.bare
          or t.variant ~ '\msold\M'
          or left(t.description, 60) ~ t.bare
          or t.description ~
               '\m(j[aá]|est[aá]|encontra-se)\s+(vendid|reservad)[oa]s?\M(?!\s*(a|com|em|no|na|para|por|pelo|pela)(\s|$|[[:punct:]]))')
     and not (t.variant ~ t.denied or t.description ~ t.denied)
  from t
$_$;

--
-- Name: stamp_favourite_seen(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stamp_favourite_seen() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  new.seen_at := now();
  select l.price, l.mileage, l.status
    into new.seen_price, new.seen_mileage, new.seen_status
    from public.listings l
   where l.id = new.listing_id;
  return new;
end;
$$;

--
-- Name: stamp_favourite_target(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stamp_favourite_target() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'INSERT' or new.target_price is distinct from old.target_price then
    new.target_set_at := case when new.target_price is null then null else now() end;
  end if;
  return new;
end;
$$;

--
-- Name: stamp_favourite_visit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stamp_favourite_visit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'INSERT' or new.visit_at is distinct from old.visit_at then
    new.visit_reminded_at := null;
  end if;
  return new;
end;
$$;

--
-- Name: start_workflow(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_workflow(p_workflow text, p_kind text DEFAULT NULL::text) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_token    text;
  v_response extensions.http_response;
  v_at       timestamptz;
begin
  if p_workflow in ('push-test.yml', 'weekly-summary.yml') then
    perform public.require_account();
  else
    perform public.require_admin();
  end if;
  if p_workflow is null
     or p_workflow not in ('collect.yml', 'weekly-summary.yml', 'push-test.yml') then
    raise exception 'unknown workflow %', p_workflow using errcode = '22023';
  end if;
  if p_kind is not null and (p_workflow <> 'push-test.yml' or p_kind not in (
       'test', 'new_listing', 'price_reduction', 'excellent_opportunity',
       'listing_removed', 'back_on_market', 'target_price_reached',
       'run_failed', 'run_blocked', 'run_recovered', 'visit_reminder',
       'bike_value_month', 'recall')) then
    raise exception 'unknown kind %', p_kind using errcode = '22023';
  end if;

  -- One at a time per workflow, so two taps can't both pass the check.
  perform pg_advisory_xact_lock(hashtext('start_workflow ' || p_workflow));
  if exists (select 1 from public.workflow_starts w
             where w.workflow = p_workflow
               and (p_workflow = 'collect.yml' or w.started_by = auth.uid())
               and w.started_at > now() - case p_workflow
                 when 'collect.yml' then interval '15 minutes'
                 when 'push-test.yml' then interval '30 seconds'
                 else interval '2 minutes' end) then
    raise exception '% was started too recently', p_workflow
      using errcode = '55006';
  end if;

  select s.decrypted_secret into v_token
  from vault.decrypted_secrets s where s.name = 'github_dispatch_token';
  if v_token is null then
    raise exception 'github_dispatch_token is not in the Vault' using errcode = '55000';
  end if;

  perform extensions.http_set_curlopt('CURLOPT_TIMEOUT_MS', '15000');
  v_response := extensions.http((
    'POST',
    'https://api.github.com/repos/rafaelfaria1323/motorcycle-deal-tracker'
      || '/actions/workflows/' || p_workflow || '/dispatches',
    array[extensions.http_header('Authorization', 'Bearer ' || v_token),
          extensions.http_header('Accept', 'application/vnd.github+json'),
          extensions.http_header('X-GitHub-Api-Version', '2022-11-28'),
          extensions.http_header('User-Agent', 'motorcycle-deal-tracker')],
    'application/json',
    case p_workflow
      when 'weekly-summary.yml' then
        jsonb_build_object('ref', 'main',
                           'inputs', jsonb_build_object('account', auth.uid()))::text
      when 'push-test.yml' then
        jsonb_build_object('ref', 'main',
                           'inputs', jsonb_build_object(
                             'account', auth.uid(),
                             'kind', coalesce(p_kind, 'test')))::text
      else '{"ref": "main"}'
    end
  )::extensions.http_request);

  -- 204 = started (200 when GitHub answers with the run's details).
  if v_response.status not in (200, 204) then
    raise exception 'GitHub answered % to %', v_response.status, p_workflow
      using errcode = '58000';
  end if;

  insert into public.workflow_starts (workflow, started_by)
  values (p_workflow, auth.uid())
  returning started_at into v_at;
  return v_at;
end;
$$;

--
-- Name: stop_sharing_favourites(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stop_sharing_favourites() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
