     and extract(hour from p_now at time zone 'Europe/Lisbon') = 8
$$;

--
-- Name: without_phone_numbers(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.without_phone_numbers(p_text text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  phone constant text :=
    '(?<![0-9])(?:(?:\+|00)?351[ .-]?)?(?:'
    || '[29][0-9]{2}[ .-]?[0-9]{3}[ .-]?[0-9]{3}'
    || '|[29][0-9]{2}[ .-][0-9]{2}[ .-][0-9]{2}[ .-][0-9]{2}'
    || '|[29][0-9][ .-][0-9]{3}[ .-][0-9]{4}'
    || ')(?![0-9])';
  t text;
begin
  if p_text is null or p_text !~ phone then
    return p_text;
  end if;
  t := regexp_replace(p_text, phone, '', 'g');
  t := regexp_replace(t, '[ \t]{2,}', ' ', 'g');
  t := regexp_replace(t, '[ \t]+(\n|$)', '\1', 'g');
  t := regexp_replace(t, '(^|\n)[ \t]+', '\1', 'g');
  t := btrim(t);
  return nullif(t, '');
end;
$_$;

--
-- Name: year_score(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.year_score(p_year integer, p_reference_year integer DEFAULT (date_part('year'::text, CURRENT_DATE))::integer, p_points_per_year integer DEFAULT 10) RETURNS smallint
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select case
    when p_year is null then null
    else greatest(0, least(100,
      100 - (p_reference_year - p_year) * p_points_per_year
    ))::smallint
  end
$$;

