);

--
-- Name: model_depreciation; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.model_depreciation WITH (security_invoker='true') AS
 WITH sample AS (
         SELECT l.motorcycle_id,
            (l.year)::numeric AS x1,
            ((l.mileage)::numeric / 1000.0) AS x2,
            ln((l.price)::numeric) AS y
           FROM public.listings l
          WHERE ((l.motorcycle_id IS NOT NULL) AND (l.status = ANY (ARRAY['active'::public.listing_status, 'price_changed'::public.listing_status])) AND (l.duplicate_of IS NULL) AND (l.price >= (300)::numeric) AND (l.year IS NOT NULL) AND (l.mileage IS NOT NULL))
        ), moments AS (
         SELECT sample.motorcycle_id,
            count(*) AS n,
            covar_pop((sample.x1)::double precision, (sample.x1)::double precision) AS s11,
            covar_pop((sample.x2)::double precision, (sample.x2)::double precision) AS s22,
            covar_pop((sample.x1)::double precision, (sample.x2)::double precision) AS s12,
            covar_pop((sample.x1)::double precision, (sample.y)::double precision) AS s1y,
            covar_pop((sample.x2)::double precision, (sample.y)::double precision) AS s2y
           FROM sample
          GROUP BY sample.motorcycle_id
        ), fit AS (
         SELECT moments.motorcycle_id,
            moments.n,
            moments.s11,
            moments.s12,
            moments.s1y,
                CASE
                    WHEN ((moments.n >= 30) AND (((moments.s11 * moments.s22) - (moments.s12 * moments.s12)) > (0)::double precision)) THEN ((- ((moments.s11 * moments.s2y) - (moments.s12 * moments.s1y))) / ((moments.s11 * moments.s22) - (moments.s12 * moments.s12)))
                    ELSE NULL::double precision
                END AS raw_per_1000km
           FROM moments
        ), km AS (
         SELECT m.id AS motorcycle_id,
            f.n,
            f.s11,
            f.s12,
            f.s1y,
            (f.raw_per_1000km IS NOT NULL) AS is_fitted,
            GREATEST(0.005,
                CASE
                    WHEN (f.raw_per_1000km IS NULL) THEN 0.002
                    ELSE round((((((f.n)::double precision * GREATEST((0)::double precision, LEAST((0.01)::double precision, f.raw_per_1000km))) + (((30)::numeric * 0.002))::double precision) / ((f.n + 30))::double precision))::numeric, 6)
                END) AS per_1000km
           FROM (public.motorcycles m
             LEFT JOIN fit f ON ((f.motorcycle_id = m.id)))
        )
 SELECT motorcycle_id,
    COALESCE(n, (0)::bigint) AS sample_count,
    is_fitted,
        CASE
            WHEN (NOT is_fitted) THEN 0.04
            ELSE round((((((n)::double precision * GREATEST((0)::double precision, LEAST((0.15)::double precision, ((s1y + ((per_1000km)::double precision * s12)) / s11)))) + (((30)::numeric * 0.04))::double precision) / ((n + 30))::double precision))::numeric, 5)
        END AS per_year,
    per_1000km
   FROM km k;

--
-- Name: listing_fair_prices; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.listing_fair_prices WITH (security_invoker='true') AS
 WITH live AS (
         SELECT l.id,
            l.source,
            l.source_listing_id,
            l.url,
            l.motorcycle_id,
            l.brand,
            l.model,
            l.variant,
            l.year,
            l.mileage,
            l.price,
            l.seller_type,
            l.seller_name,
            l.location,
            l.description,
            l.images,
            l.status,
            l.first_seen_at,
            l.last_seen_at,
            l.last_checked_at,
            l.created_at,
            l.updated_at,
            l.deal_score,
            l.risk_score,
            l.score_breakdown,
            l.scored_at,
            l.duplicate_of,
            l.duplicate_score,
            l.initial_price,
            l.excellent_since,
            l.registrations,
            l.service_book,
            l.origin,
            l.warranty_until,
            l.dealer_warranty_months,
            l.published_at,
            l.details_checked_at,
            l.price_before_drop,
            l.search_key,
            l.site_refreshed_at,
            l.relisted_from,
            l.relisted_since,
            l.relisted_price
           FROM public.listings l
          WHERE ((l.motorcycle_id IS NOT NULL) AND (l.status = ANY (ARRAY['active'::public.listing_status, 'price_changed'::public.listing_status])) AND (l.duplicate_of IS NULL) AND (l.price >= (300)::numeric))
        ), pairs AS (
         SELECT l.id,
            l.year AS l_year,
            l.mileage AS l_mileage,
            l.motorcycle_id,
            c.id AS c_id,
            c.year AS c_year,
            c.mileage AS c_mileage,
            c.price AS c_price,
            (abs((l.year - c.year)) <= 3) AS near
           FROM (live l
             JOIN live c ON (((c.motorcycle_id = l.motorcycle_id) AND (c.id <> l.id) AND ((l.year IS NULL) OR (c.year IS NOT NULL)) AND ((l.mileage IS NULL) OR (c.mileage IS NOT NULL)))))
        ), chosen AS (
         SELECT p.id,
            p.l_year,
            p.l_mileage,
            p.motorcycle_id,
            p.c_id,
            p.c_year,
            p.c_mileage,
            p.c_price,
            p.near,
            (count(*) FILTER (WHERE p.near) OVER (PARTITION BY p.id) >= 5) AS use_near
           FROM pairs p
        )
 SELECT ch.id AS listing_id,
    count(ch.c_id) AS comparable_count,
    round((percentile_cont((0.5)::double precision) WITHIN GROUP (ORDER BY (((ch.c_price * public.age_mileage_factor(((ch.l_year - ch.c_year))::integer, (ch.l_mileage - ch.c_mileage), d.per_year, d.per_1000km)))::double precision)))::numeric, 2) AS fair_price
   FROM (chosen ch
     JOIN public.model_depreciation d ON ((d.motorcycle_id = ch.motorcycle_id)))
  WHERE ((NOT ch.use_near) OR ch.near)
  GROUP BY ch.id;

--
-- Name: listing_new_price_comparison; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.listing_new_price_comparison WITH (security_invoker='true') AS
 SELECT l.id AS listing_id,
    l.motorcycle_id,
    l.price AS used_price,
    COALESCE(m.new_price_from_ads, m.new_price_reference) AS new_price,
    (COALESCE(m.new_price_from_ads, m.new_price_reference) - l.price) AS difference,
    round((((COALESCE(m.new_price_from_ads, m.new_price_reference) - l.price) / NULLIF(COALESCE(m.new_price_from_ads, m.new_price_reference), (0)::numeric)) * (100)::numeric), 1) AS difference_pct
   FROM (public.listings l
     JOIN public.motorcycles m ON ((m.id = l.motorcycle_id)))
  WHERE ((l.price IS NOT NULL) AND (COALESCE(m.new_price_from_ads, m.new_price_reference) IS NOT NULL));

