--
-- Name: listing_price_scores; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.listing_price_scores WITH (security_invoker='true') AS
 SELECT l.id AS listing_id,
    l.motorcycle_id,
    l.price,
    f.fair_price AS market_price,
    f.comparable_count AS listing_count,
    round((((f.fair_price - l.price) / f.fair_price) * (100)::numeric), 1) AS pct_below_market,
        CASE
            WHEN (f.comparable_count >= 3) THEN public.price_score(l.price, f.fair_price, 2.5)
            ELSE NULL::smallint
        END AS price_score,
    (f.comparable_count >= 3) AS is_reliable
   FROM (public.listings l
     JOIN public.listing_fair_prices f ON ((f.listing_id = l.id)))
  WHERE ((l.status = ANY (ARRAY['active'::public.listing_status, 'price_changed'::public.listing_status])) AND (l.duplicate_of IS NULL) AND (l.price IS NOT NULL));

--
-- Name: listing_risk_scores; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.listing_risk_scores WITH (security_invoker='true') AS
 SELECT l.id AS listing_id,
    r.risk_score,
    r.reasons
   FROM (((public.listings l
     LEFT JOIN public.listing_fair_prices f ON ((f.listing_id = l.id)))
     LEFT JOIN public.listings prev ON ((prev.id = l.relisted_from)))
     CROSS JOIN LATERAL public.risk_from_signals(l.price,
        CASE
            WHEN (f.comparable_count >= 3) THEN f.fair_price
            ELSE NULL::numeric
        END, (l.year)::integer, l.mileage, l.description, l.location, ((l.details_checked_at IS NOT NULL) OR (l.source = 'olx'::text)), COALESCE(((l.seller_type)::text = 'private'::text), false), (l.registrations)::integer, l.service_book, l.origin, l.warranty_until, (((l.relisted_from IS NOT NULL))::integer + ((prev.relisted_from IS NOT NULL))::integer), l.relisted_since, (((COALESCE(l.text_signals, public.description_signals(l.variant, l.description)) ||
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM (public.listing_photo_matches m
                 JOIN public.listings o ON ((o.id = m.other_id)))
              WHERE ((m.listing_id = l.id) AND (o.first_seen_at < l.first_seen_at) AND ((o.motorcycle_id <> l.motorcycle_id) OR ((l.seller_type = 'private'::public.seller_type) AND (o.seller_type = 'dealer'::public.seller_type)))))) THEN ARRAY['photos_reused'::text]
            ELSE '{}'::text[]
        END) ||
        CASE
            WHEN (l.stock_photos AND (NOT ((l.seller_type = 'dealer'::public.seller_type) AND (l.mileage <= 100)))) THEN ARRAY['stock_photos'::text]
            ELSE '{}'::text[]
        END) || public.fact_edit_signals(l.mileage, l.mileage_from_text, l.mileage_max_seen, (l.year)::integer, (l.year_first_seen)::integer))) r(risk_score, reasons))
  WHERE (l.status = ANY (ARRAY['active'::public.listing_status, 'price_changed'::public.listing_status]));

--
-- Name: model_market_behaviour; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.model_market_behaviour WITH (security_invoker='true') AS
 WITH base AS (
         SELECT l.motorcycle_id,
            l.status,
            l.price,
            GREATEST(l.initial_price, l.price_before_drop) AS initial_price,
            COALESCE(l.published_at, l.first_seen_at) AS listed_at,
            l.last_seen_at,
            (l.status = ANY (ARRAY['removed'::public.listing_status, 'sold'::public.listing_status])) AS gone,
            GREATEST((0)::numeric, (EXTRACT(epoch FROM (
                CASE
                    WHEN (l.status = ANY (ARRAY['removed'::public.listing_status, 'sold'::public.listing_status])) THEN l.last_seen_at
                    ELSE now()
                END - COALESCE(l.published_at, l.first_seen_at))) / (86400)::numeric)) AS days
           FROM public.listings l
          WHERE ((l.motorcycle_id IS NOT NULL) AND (l.duplicate_of IS NULL) AND (NOT ((l.status = ANY (ARRAY['removed'::public.listing_status, 'sold'::public.listing_status])) AND ((l.last_seen_at - l.first_seen_at) < '01:00:00'::interval))))
        )
 SELECT motorcycle_id,
    count(*) FILTER (WHERE (status = ANY (ARRAY['active'::public.listing_status, 'price_changed'::public.listing_status]))) AS live_count,
    count(*) FILTER (WHERE gone) AS gone_count,
    round(public.median_days_remaining(array_agg(days) FILTER (WHERE (gone OR (status = ANY (ARRAY['active'::public.listing_status, 'price_changed'::public.listing_status])))), array_agg(gone) FILTER (WHERE (gone OR (status = ANY (ARRAY['active'::public.listing_status, 'price_changed'::public.listing_status])))), (0)::numeric)) AS median_days_to_gone,
    round((percentile_cont((0.5)::double precision) WITHIN GROUP (ORDER BY (((EXTRACT(epoch FROM (now() - listed_at)) / (86400)::numeric))::double precision)) FILTER (WHERE (status = ANY (ARRAY['active'::public.listing_status, 'price_changed'::public.listing_status]))))::numeric, 0) AS median_days_listed_live,
    count(*) FILTER (WHERE (initial_price IS NOT NULL)) AS priced_count,
    count(*) FILTER (WHERE ((initial_price IS NOT NULL) AND (price < initial_price))) AS dropped_count,
    round((percentile_cont((0.5)::double precision) WITHIN GROUP (ORDER BY (((((initial_price - price) / initial_price) * (100)::numeric))::double precision)) FILTER (WHERE ((initial_price IS NOT NULL) AND (price < initial_price))))::numeric, 1) AS median_drop_pct
   FROM base
  GROUP BY motorcycle_id;

--
-- Name: model_market_stats; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.model_market_stats WITH (security_invoker='true') AS
 SELECT motorcycle_id,
    count(*) AS listing_count,
    round(avg(price), 2) AS avg_price,
    round((percentile_cont((0.5)::double precision) WITHIN GROUP (ORDER BY ((price)::double precision)))::numeric, 2) AS median_price,
    min(price) AS min_price,
    max(price) AS max_price
   FROM public.listings
  WHERE ((motorcycle_id IS NOT NULL) AND (price IS NOT NULL) AND (status = ANY (ARRAY['active'::public.listing_status, 'price_changed'::public.listing_status])) AND (duplicate_of IS NULL))
  GROUP BY motorcycle_id;

--
-- Name: model_price_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.model_price_summary WITH (security_invoker='true') AS
 SELECT motorcycle_id,
    count(*) AS priced_live_count,
    min(price) AS min_price,
    round((percentile_cont((0.25)::double precision) WITHIN GROUP (ORDER BY ((price)::double precision)))::numeric, 0) AS p25_price,
    round((percentile_cont((0.5)::double precision) WITHIN GROUP (ORDER BY ((price)::double precision)))::numeric, 0) AS median_price,
    round((percentile_cont((0.75)::double precision) WITHIN GROUP (ORDER BY ((price)::double precision)))::numeric, 0) AS p75_price,
    max(price) AS max_price,
    round((percentile_cont((0.5)::double precision) WITHIN GROUP (ORDER BY ((year)::double precision)))::numeric, 0) AS median_year,
    round((percentile_cont((0.5)::double precision) WITHIN GROUP (ORDER BY ((mileage)::double precision)))::numeric, 0) AS median_mileage
   FROM public.listings l
  WHERE ((motorcycle_id IS NOT NULL) AND (status = ANY (ARRAY['active'::public.listing_status, 'price_changed'::public.listing_status])) AND (duplicate_of IS NULL) AND (price IS NOT NULL))
  GROUP BY motorcycle_id;

--
-- Name: model_price_trend; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.model_price_trend WITH (security_invoker='true') AS
 WITH weeks AS (
         SELECT w.w AS week_start
           FROM generate_series((date_trunc('week'::text, now()) - '77 days'::interval), date_trunc('week'::text, now()), '7 days'::interval) w(w)
        ), seen AS (
         SELECT l.motorcycle_id,
            wk.week_start,
            l.year,
            l.mileage,
            COALESCE(( SELECT h.price
                   FROM public.listing_price_history h
                  WHERE ((h.listing_id = l.id) AND (h.observed_at < (wk.week_start + '7 days'::interval)))
                  ORDER BY h.observed_at DESC
                 LIMIT 1), l.price) AS price
           FROM (public.listings l
             JOIN weeks wk ON (((l.first_seen_at < (wk.week_start + '7 days'::interval)) AND (l.last_seen_at >= wk.week_start))))
          WHERE ((l.motorcycle_id IS NOT NULL) AND (l.duplicate_of IS NULL))
        ), adjusted AS (
         SELECT s.motorcycle_id,
            s.week_start,
            s.price,
            (s.price * public.age_mileage_factor(((ps.median_year - (s.year)::numeric))::integer, ((ps.median_mileage - (s.mileage)::numeric))::integer, COALESCE(d.per_year, 0.04), COALESCE(d.per_1000km, 0.002))) AS adjusted_price
           FROM ((seen s
             LEFT JOIN public.model_price_summary ps ON ((ps.motorcycle_id = s.motorcycle_id)))
             LEFT JOIN public.model_depreciation d ON ((d.motorcycle_id = s.motorcycle_id)))
          WHERE (s.price >= (300)::numeric)
        )
 SELECT motorcycle_id,
    (week_start)::date AS week_start,
    count(*) AS listing_count,
    round((percentile_cont((0.5)::double precision) WITHIN GROUP (ORDER BY ((price)::double precision)))::numeric, 0) AS median_price,
    round((percentile_cont((0.5)::double precision) WITHIN GROUP (ORDER BY ((adjusted_price)::double precision)))::numeric, 0) AS median_adjusted_price
   FROM adjusted
  GROUP BY motorcycle_id, week_start;

