    model_name text NOT NULL,
    ads integer,
    seen_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT site_models_ads_check CHECK ((ads >= 0)),
    CONSTRAINT site_models_source_check CHECK ((source = ANY (ARRAY['standvirtual'::text, 'olx'::text])))
);

--
-- Name: TABLE site_models; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.site_models IS 'Brands and models in the sites'' search filters (ids go into search addresses).';

--
-- Name: site_makes; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.site_makes WITH (security_invoker='true') AS
 SELECT make_id,
    make_name,
    (COALESCE(sum(ads), (0)::bigint))::integer AS ads
   FROM public.site_models
  WHERE (source = 'standvirtual'::text)
  GROUP BY make_id, make_name;

--
-- Name: source_data_quality; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.source_data_quality WITH (security_invoker='true') AS
 WITH steps AS (
         SELECT h.listing_id,
            h.observed_at,
            h.price,
            lag(h.price) OVER (PARTITION BY h.listing_id ORDER BY h.observed_at, h.id) AS previous_price
           FROM public.listing_price_history h
        ), sharp AS (
         SELECT DISTINCT s.listing_id
           FROM steps s
          WHERE ((s.observed_at >= (now() - '30 days'::interval)) AND (s.previous_price > (0)::numeric) AND ((s.price >= (s.previous_price * 1.5)) OR (s.price <= (s.previous_price * 0.5))))
        )
 SELECT source,
    count(*) AS live_count,
    count(*) FILTER (WHERE (motorcycle_id IS NULL)) AS unmatched_count,
    count(*) FILTER (WHERE (duplicate_of IS NOT NULL)) AS duplicate_count,
    count(*) FILTER (WHERE ((motorcycle_id IS NOT NULL) AND (duplicate_of IS NULL))) AS scored_count,
    count(*) FILTER (WHERE ((motorcycle_id IS NOT NULL) AND (duplicate_of IS NULL) AND (year IS NULL))) AS missing_year,
    count(*) FILTER (WHERE ((motorcycle_id IS NOT NULL) AND (duplicate_of IS NULL) AND (mileage IS NULL))) AS missing_mileage,
    count(*) FILTER (WHERE ((motorcycle_id IS NOT NULL) AND (duplicate_of IS NULL) AND (NULLIF(TRIM(BOTH FROM location), ''::text) IS NULL))) AS missing_location,
    count(*) FILTER (WHERE ((source = 'standvirtual'::text) AND (motorcycle_id IS NOT NULL) AND (duplicate_of IS NULL) AND (details_checked_at IS NULL))) AS details_pending,
    max(last_seen_at) AS last_seen_at,
    count(*) FILTER (WHERE (id IN ( SELECT sharp.listing_id
           FROM sharp))) AS sharp_price_changes
   FROM public.listings l
  WHERE (status = ANY (ARRAY['active'::public.listing_status, 'price_changed'::public.listing_status]))
  GROUP BY source;

